const INDEX_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\" />\n  <title>Aryush Foods \u2014 Lucky Draw Coupon & Prize Manager</title>\n  <link rel=\"manifest\" href=\"/manifest.json\" />\n  <meta name=\"theme-color\" content=\"#0f172a\" />\n  <!-- jsPDF & AutoTable for crisp, multi-page vector PDF generation (never blank!) -->\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js\"></script>\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.8.2/jspdf.plugin.autotable.min.js\"></script>\n  <style>\n    :root {\n      --navy: #0f172a;\n      --navy-light: #1e293b;\n      --brand: #d97706;\n      --brand-dark: #b45309;\n      --brand-soft: #fef3c7;\n      --teal: #0d9488;\n      --teal-soft: #ccfbf1;\n      --green: #16a34a;\n      --green-soft: #dcfce7;\n      --red: #dc2626;\n      --red-soft: #fee2e2;\n      --blue: #2563eb;\n      --blue-soft: #dbeafe;\n      --bg: #f1f5f9;\n      --card: #ffffff;\n      --text: #0f172a;\n      --muted: #64748b;\n      --border: #e2e8f0;\n      --radius: 14px;\n      --shadow: 0 2px 10px rgba(15, 23, 42, 0.06);\n    }\n    * { box-sizing: border-box; margin: 0; padding: 0; font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Inter, sans-serif; }\n    body { background: var(--bg); color: var(--text); padding-bottom: 84px; min-height: 100vh; }\n\n    /* Top Header */\n    .topbar {\n      background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);\n      color: #fff;\n      padding: 14px 18px;\n      position: sticky;\n      top: 0;\n      z-index: 50;\n      box-shadow: 0 4px 16px rgba(15,23,42,0.18);\n    }\n    .topbar-inner {\n      max-width: 1220px;\n      margin: 0 auto;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 12px;\n      flex-wrap: wrap;\n    }\n    .brand-wrap { display: flex; align-items: center; gap: 12px; }\n    .brand-logo {\n      width: 42px; height: 42px; border-radius: 11px;\n      background: linear-gradient(135deg, #f59e0b, #d97706);\n      display: flex; align-items: center; justify-content: center;\n      font-weight: 800; font-size: 19px; color: #fff;\n      box-shadow: 0 3px 10px rgba(245,158,11,0.35);\n      flex-shrink: 0;\n    }\n    .brand-title { font-size: 16px; font-weight: 800; letter-spacing: 0.3px; color: #fbbf24; }\n    .brand-sub { font-size: 12.5px; color: #cbd5e1; margin-top: 1px; }\n    .top-actions { display: flex; align-items: center; gap: 8px; }\n    .sync-pill {\n      font-size: 11.5px; font-weight: 600; padding: 5px 10px; border-radius: 999px;\n      background: rgba(16,185,129,0.16); color: #6ee7b7; border: 1px solid rgba(16,185,129,0.35);\n      display: inline-flex; align-items: center; gap: 6px;\n    }\n    .sync-pill.local { background: rgba(245,158,11,0.18); color: #fcd34d; border-color: rgba(245,158,11,0.35); }\n    .dot { width: 7px; height: 7px; border-radius: 50%; background: currentColor; }\n\n    /* Desktop Nav Tabs */\n    .nav-tabs {\n      background: #fff;\n      border-bottom: 1px solid var(--border);\n      position: sticky;\n      top: 70px;\n      z-index: 40;\n    }\n    .nav-tabs-inner {\n      max-width: 1220px;\n      margin: 0 auto;\n      display: flex;\n      gap: 4px;\n      overflow-x: auto;\n      padding: 6px 14px;\n      scrollbar-width: none;\n    }\n    .nav-tabs-inner::-webkit-scrollbar { display: none; }\n    .tab-btn {\n      border: none; background: transparent; color: var(--muted);\n      padding: 9px 15px; border-radius: 10px; font-size: 13.5px; font-weight: 700;\n      cursor: pointer; white-space: nowrap; display: inline-flex; align-items: center; gap: 7px;\n      transition: all 0.15s ease;\n    }\n    .tab-btn:hover { background: #f8fafc; color: var(--navy); }\n    .tab-btn.active { background: var(--navy); color: #fbbf24; box-shadow: 0 2px 6px rgba(15,23,42,0.15); }\n    .tab-badge {\n      background: #ef4444; color: #fff; font-size: 11px; font-weight: 800;\n      padding: 1px 6px; border-radius: 999px;\n    }\n\n    /* Main Container */\n    .container { max-width: 1220px; margin: 18px auto; padding: 0 14px; }\n    .screen { display: none; animation: fadeIn 0.16s ease; }\n    .screen.active { display: block; }\n    @keyframes fadeIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }\n\n    /* KPI Grid */\n    .kpi-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(175px, 1fr));\n      gap: 12px;\n      margin-bottom: 18px;\n    }\n    .kpi-card {\n      background: var(--card); border: 1px solid var(--border); border-radius: var(--radius);\n      padding: 14px 16px; box-shadow: var(--shadow); position: relative; overflow: hidden;\n    }\n    .kpi-card::before {\n      content: \"\"; position: absolute; left: 0; top: 0; bottom: 0; width: 4px; background: var(--navy);\n    }\n    .kpi-card.amber::before { background: var(--brand); }\n    .kpi-card.green::before { background: var(--green); }\n    .kpi-card.teal::before { background: var(--teal); }\n    .kpi-card.blue::before { background: var(--blue); }\n    .kpi-card.red::before { background: var(--red); }\n    .kpi-label { font-size: 11.5px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.4px; color: var(--muted); }\n    .kpi-val { font-size: 25px; font-weight: 800; color: var(--text); margin: 5px 0 3px; }\n    .kpi-sub { font-size: 12px; color: var(--muted); font-weight: 500; }\n\n    /* Cards */\n    .card {\n      background: var(--card); border: 1px solid var(--border); border-radius: var(--radius);\n      padding: 18px; box-shadow: var(--shadow); margin-bottom: 16px;\n    }\n    .card-header {\n      display: flex; align-items: center; justify-content: space-between; gap: 10px;\n      flex-wrap: wrap; margin-bottom: 14px; padding-bottom: 11px; border-bottom: 1px solid var(--border);\n    }\n    .card-title { font-size: 16px; font-weight: 800; color: var(--navy); display: flex; align-items: center; gap: 8px; }\n    .card-sub { font-size: 12.5px; color: var(--muted); margin-top: 2px; }\n\n    /* Forms & Inputs */\n    .form-grid {\n      display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 12px; align-items: end;\n    }\n    .field { display: flex; flex-direction: column; gap: 5px; }\n    .field label { font-size: 12px; font-weight: 700; color: #334155; }\n    input, select, textarea {\n      width: 100%; padding: 10px 12px; border: 1.5px solid #cbd5e1; border-radius: 10px;\n      font-size: 14px; color: var(--text); background: #fff; outline: none; transition: border-color 0.15s;\n    }\n    input:focus, select:focus, textarea:focus { border-color: var(--brand); box-shadow: 0 0 0 3px rgba(217,119,6,0.12); }\n\n    /* Buttons */\n    .btn {\n      border: none; border-radius: 10px; padding: 10px 16px; font-size: 13.5px; font-weight: 700;\n      cursor: pointer; display: inline-flex; align-items: center; justify-content: center; gap: 7px;\n      transition: all 0.15s ease; text-decoration: none;\n    }\n    .btn:disabled { opacity: 0.55; cursor: not-allowed; }\n    .btn-primary { background: var(--navy); color: #fbbf24; }\n    .btn-primary:hover:not(:disabled) { background: #1e293b; }\n    .btn-brand { background: linear-gradient(135deg, #f59e0b, #d97706); color: #fff; box-shadow: 0 3px 10px rgba(217,119,6,0.28); }\n    .btn-brand:hover:not(:disabled) { filter: brightness(1.05); }\n    .btn-green { background: var(--green); color: #fff; }\n    .btn-green:hover:not(:disabled) { background: #15803d; }\n    .btn-outline { background: #fff; color: var(--navy); border: 1.5px solid #cbd5e1; }\n    .btn-outline:hover:not(:disabled) { background: #f8fafc; border-color: #94a3b8; }\n    .btn-danger { background: var(--red-soft); color: var(--red); }\n    .btn-danger:hover:not(:disabled) { background: #fecaca; }\n    .btn-sm { padding: 6px 11px; font-size: 12px; border-radius: 8px; }\n\n    /* Chips */\n    .chip-row { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }\n    .chip {\n      border: 1px solid #cbd5e1; background: #f8fafc; color: #334155;\n      padding: 4px 10px; border-radius: 999px; font-size: 12px; font-weight: 700; cursor: pointer;\n    }\n    .chip:hover { background: var(--brand-soft); border-color: var(--brand); color: var(--brand-dark); }\n\n    /* Tables */\n    .table-wrap { width: 100%; overflow-x: auto; border: 1px solid var(--border); border-radius: 11px; }\n    table { width: 100%; border-collapse: collapse; min-width: 640px; background: #fff; }\n    th {\n      background: #f8fafc; color: #475569; font-size: 11.5px; font-weight: 800;\n      text-transform: uppercase; letter-spacing: 0.4px; padding: 11px 12px; text-align: left;\n      border-bottom: 1.5px solid var(--border);\n    }\n    td { padding: 10px 12px; font-size: 13.5px; border-bottom: 1px solid #f1f5f9; vertical-align: middle; }\n    tr:last-child td { border-bottom: none; }\n    tr:hover td { background: #fcfcfd; }\n    .num { text-align: right; font-variant-numeric: tabular-nums; }\n\n    /* Badges */\n    .badge {\n      display: inline-flex; align-items: center; gap: 4px; padding: 3px 9px;\n      border-radius: 999px; font-size: 11.5px; font-weight: 700;\n    }\n    .badge-green { background: var(--green-soft); color: #15803d; }\n    .badge-amber { background: var(--brand-soft); color: #b45309; }\n    .badge-blue { background: var(--blue-soft); color: #1d4ed8; }\n    .badge-teal { background: var(--teal-soft); color: #0f766e; }\n    .badge-gray { background: #f1f5f9; color: #475569; }\n    .badge-red { background: var(--red-soft); color: var(--red); }\n\n    /* Progress bar */\n    .prog-track { width: 100%; height: 8px; background: #e2e8f0; border-radius: 999px; overflow: hidden; margin-top: 4px; }\n    .prog-fill { height: 100%; background: linear-gradient(90deg, #0d9488, #16a34a); border-radius: 999px; transition: width 0.25s ease; }\n    .prog-fill.amber { background: linear-gradient(90deg, #f59e0b, #d97706); }\n\n    /* Hero Allot Box */\n    .hero-box {\n      background: linear-gradient(135deg, #fffbeb 0%, #fef3c7 100%);\n      border: 1.5px solid #fcd34d; border-radius: var(--radius); padding: 18px; margin-bottom: 16px;\n    }\n    .winner-preview-box {\n      background: linear-gradient(135deg, #ecfdf5 0%, #d1fae5 100%);\n      border: 1.5px solid #6ee7b7; border-radius: 12px; padding: 13px 15px; margin-top: 10px;\n    }\n\n    /* Bottom Mobile Bar */\n    .bottom-nav {\n      display: none; position: fixed; bottom: 0; left: 0; right: 0; background: #fff;\n      border-top: 1px solid var(--border); z-index: 60; box-shadow: 0 -3px 12px rgba(15,23,42,0.08);\n    }\n    .bottom-nav-inner { display: grid; grid-template-columns: repeat(5, 1fr); }\n    .bnav-btn {\n      border: none; background: transparent; padding: 8px 4px; display: flex; flex-direction: column;\n      align-items: center; gap: 3px; color: var(--muted); font-size: 10.5px; font-weight: 700; cursor: pointer;\n    }\n    .bnav-btn .ico { font-size: 18px; }\n    .bnav-btn.active { color: var(--brand-dark); background: #fffbeb; }\n\n    /* Modals */\n    .modal-backdrop {\n      display: none; position: fixed; inset: 0; background: rgba(15,23,42,0.58);\n      z-index: 100; align-items: center; justify-content: center; padding: 14px;\n    }\n    .modal-backdrop.open { display: flex; }\n    .modal {\n      background: #fff; border-radius: 16px; width: 100%; max-width: 650px; max-height: 90vh;\n      overflow-y: auto; padding: 20px; box-shadow: 0 20px 50px rgba(0,0,0,0.25);\n    }\n    .modal-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 14px; padding-bottom: 10px; border-bottom: 1px solid var(--border); }\n\n    /* Toast */\n    #toast {\n      position: fixed; bottom: 88px; right: 16px; background: #0f172a; color: #fff;\n      padding: 11px 16px; border-radius: 11px; font-size: 13.5px; font-weight: 600;\n      box-shadow: 0 8px 24px rgba(0,0,0,0.22); z-index: 200; display: none;\n    }\n\n    /* Report Grid */\n    .report-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(265px, 1fr)); gap: 14px; }\n    .report-card {\n      border: 1.5px solid var(--border); border-radius: 13px; padding: 16px; background: #fff;\n      display: flex; flex-direction: column; justify-content: space-between; gap: 12px;\n    }\n\n    /* Print Area */\n    #printSection { display: none; }\n    @media (max-width: 768px) {\n      .nav-tabs { display: none; }\n      .bottom-nav { display: block; }\n      .kpi-val { font-size: 21px; }\n    }\n    @media print {\n      body * { visibility: hidden !important; }\n      #printSection, #printSection * { visibility: visible !important; }\n      #printSection {\n        display: block !important; position: absolute; left: 0; top: 0; width: 100%;\n        background: #fff; color: #000; padding: 10px;\n      }\n      .print-table { width: 100%; border-collapse: collapse; margin-top: 12px; }\n      .print-table th, .print-table td { border: 1px solid #334155; padding: 6px 8px; font-size: 11.5px; text-align: left; }\n      .print-table th { background: #e2e8f0 !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }\n    }\n  </style>\n</head>\n<body>\n\n  <!-- Top Header -->\n  <header class=\"topbar\">\n    <div class=\"topbar-inner\">\n      <div class=\"brand-wrap\">\n        <div class=\"brand-logo\">AF</div>\n        <div>\n          <div class=\"brand-title\" id=\"hdrCompany\">ARYUSH FOODS \u2014 MEGA ALTO LUCKY DRAW</div>\n          <div class=\"brand-sub\" id=\"hdrSub\">1 Coupon per 210 kg (7 Bags \u00d7 30 kg) \u2022 Pool: 300 Coupons</div>\n        </div>\n      </div>\n      <div class=\"top-actions\">\n        <span class=\"sync-pill\" id=\"syncBadge\"><span class=\"dot\"></span> <span id=\"syncText\">Connecting...</span></span>\n        <button class=\"btn btn-outline btn-sm\" style=\"background:rgba(255,255,255,0.1);color:#fff;border-color:rgba(255,255,255,0.25);\" onclick=\"refreshAll()\">\u21bb Sync</button>\n      </div>\n    </div>\n  </header>\n\n  <!-- Desktop Navigation -->\n  <nav class=\"nav-tabs\">\n    <div class=\"nav-tabs-inner\">\n      <button class=\"tab-btn active\" data-tab=\"overview\" onclick=\"switchTab('overview')\">\ud83d\udcca Overview & Summary</button>\n      <button class=\"tab-btn\" data-tab=\"deliveries\" onclick=\"switchTab('deliveries')\">\ud83d\ude9a Delivery Entry & Log</button>\n      <button class=\"tab-btn\" data-tab=\"allot\" onclick=\"switchTab('allot')\">\ud83c\udf9f\ufe0f Allot Coupons (Ek Sath) <span class=\"tab-badge\" id=\"navPendingBadge\" style=\"display:none\">0</span></button>\n      <button class=\"tab-btn\" data-tab=\"prizes\" onclick=\"switchTab('prizes')\">\ud83c\udfc6 Lucky Draw & Prize Entry</button>\n      <button class=\"tab-btn\" data-tab=\"reports\" onclick=\"switchTab('reports')\">\ud83d\udcc4 PDF Reports & Settings</button>\n    </div>\n  </nav>\n\n  <main class=\"container\">\n\n    <!-- ================= TAB 1: OVERVIEW ================= -->\n    <section id=\"screen-overview\" class=\"screen active\">\n      <div class=\"kpi-grid\">\n        <div class=\"kpi-card\">\n          <div class=\"kpi-label\">Total KG Delivered</div>\n          <div class=\"kpi-val\" id=\"kpiTotalKg\">0 kg</div>\n          <div class=\"kpi-sub\" id=\"kpiTotalBags\">0 Bags (30 kg)</div>\n        </div>\n        <div class=\"kpi-card teal\">\n          <div class=\"kpi-label\">Coupons Earned</div>\n          <div class=\"kpi-val\" id=\"kpiEarned\">0</div>\n          <div class=\"kpi-sub\" id=\"kpiEarnedSub\">Target: 210 kg / coupon</div>\n        </div>\n        <div class=\"kpi-card blue\">\n          <div class=\"kpi-label\">Coupons Allotted</div>\n          <div class=\"kpi-val\" id=\"kpiIssued\">0</div>\n          <div class=\"kpi-sub\" id=\"kpiPoolPct\">0% of 300 pool</div>\n        </div>\n        <div class=\"kpi-card amber\">\n          <div class=\"kpi-label\">Pending to Allot</div>\n          <div class=\"kpi-val\" id=\"kpiPending\">0</div>\n          <div class=\"kpi-sub\"><a href=\"javascript:void(0)\" onclick=\"switchTab('allot')\" style=\"color:var(--brand-dark);font-weight:700;\">Allot Ek Sath \u2192</a></div>\n        </div>\n        <div class=\"kpi-card green\">\n          <div class=\"kpi-label\">Coupons Available</div>\n          <div class=\"kpi-val\" id=\"kpiAvailable\">300</div>\n          <div class=\"kpi-sub\" id=\"kpiRetailerCount\">0 Retailers buying</div>\n        </div>\n        <div class=\"kpi-card red\">\n          <div class=\"kpi-label\">Prizes Declared</div>\n          <div class=\"kpi-val\" id=\"kpiWinners\">0</div>\n          <div class=\"kpi-sub\"><a href=\"javascript:void(0)\" onclick=\"switchTab('reports')\" style=\"color:var(--red);font-weight:700;\">Download Prize PDF \u2192</a></div>\n        </div>\n      </div>\n\n      <!-- Overall Pool Completion Banner -->\n      <div class=\"card\" style=\"padding:14px 18px;\">\n        <div style=\"display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;\">\n          <div>\n            <strong id=\"poolBannerTitle\" style=\"font-size:14.5px;\">Scheme Coupon Pool Progress (0 / 300 Earned)</strong>\n            <div style=\"font-size:12.5px;color:var(--muted);\" id=\"poolBannerSub\">Jab coupons pure ho jayein, 'Allot Coupons' tab se 1-Click me ek sath allot karein.</div>\n          </div>\n          <div style=\"display:flex;gap:8px;\">\n            <button class=\"btn btn-brand btn-sm\" onclick=\"switchTab('deliveries')\">+ New Delivery</button>\n            <button class=\"btn btn-primary btn-sm\" onclick=\"switchTab('allot')\">\ud83c\udf9f\ufe0f Allot Ek Sath</button>\n          </div>\n        </div>\n        <div class=\"prog-track\" style=\"height:10px;margin-top:10px;\">\n          <div class=\"prog-fill amber\" id=\"poolProgBar\" style=\"width:0%\"></div>\n        </div>\n      </div>\n\n      <!-- Retailer Summary Table -->\n      <div class=\"card\">\n        <div class=\"card-header\">\n          <div>\n            <div class=\"card-title\">\ud83c\udfea Retailer-wise Purchase & Coupon Summary</div>\n            <div class=\"card-sub\">Har retailer ka kul maal (kg/bags), agle coupon ki progress, earned aur allotted coupon numbers</div>\n          </div>\n          <div style=\"display:flex;gap:8px;flex-wrap:wrap;\">\n            <input type=\"text\" id=\"sumSearch\" placeholder=\"\ud83d\udd0d Search retailer or area...\" oninput=\"renderOverview()\" style=\"width:210px;\" />\n            <select id=\"sumFilter\" onchange=\"renderOverview()\" style=\"width:175px;\">\n              <option value=\"ALL\">All Retailers</option>\n              <option value=\"PENDING\">Pending Allotment (>0)</option>\n              <option value=\"EARNED\">Coupons Earned (>0)</option>\n              <option value=\"NEAR\">Near Next Coupon (\u2265150 kg)</option>\n              <option value=\"WINNERS\">Prize Winners \ud83c\udfc6</option>\n            </select>\n            <button class=\"btn btn-outline btn-sm\" onclick=\"openRetailerModal()\">+ Add Retailer</button>\n          </div>\n        </div>\n        <div class=\"table-wrap\">\n          <table>\n            <thead>\n              <tr>\n                <th>#</th>\n                <th>Retailer Name</th>\n                <th class=\"num\">Bags (30kg)</th>\n                <th class=\"num\">Total KG</th>\n                <th>Next Coupon Progress</th>\n                <th class=\"num\">Earned</th>\n                <th class=\"num\">Issued</th>\n                <th class=\"num\">Pending</th>\n                <th>Allotted Coupon Nos.</th>\n                <th>Action</th>\n              </tr>\n            </thead>\n            <tbody id=\"summaryTbody\"></tbody>\n          </table>\n        </div>\n      </div>\n    </section>\n\n    <!-- ================= TAB 2: DELIVERIES ================= -->\n    <section id=\"screen-deliveries\" class=\"screen\">\n      <div class=\"card\">\n        <div class=\"card-header\">\n          <div>\n            <div class=\"card-title\" id=\"delFormTitle\">\ud83d\ude9a New Delivery Entry</div>\n            <div class=\"card-sub\">1 Bag = <span class=\"lblBagKg\">30</span> kg \u2022 <span class=\"lblCouponKg\">210</span> kg = 1 Coupon (Coupons allot tab me ek sath honge)</div>\n          </div>\n          <div style=\"display:flex;gap:8px;flex-wrap:wrap;\">\n            <button class=\"btn btn-outline btn-sm\" onclick=\"openRetailerModal()\">+ New Retailer</button>\n            <button class=\"btn btn-outline btn-sm\" onclick=\"openBulkImportModal()\">\ud83d\udccb Sheet se Bulk Paste</button>\n          </div>\n        </div>\n\n        <input type=\"hidden\" id=\"editDeliveryId\" value=\"\" />\n        <div class=\"form-grid\">\n          <div class=\"field\">\n            <label>Delivery Date *</label>\n            <input type=\"date\" id=\"delDate\" />\n          </div>\n          <div class=\"field\" style=\"grid-column: span 2; min-width: 240px;\">\n            <label>Select or Type Retailer Name *</label>\n            <input type=\"text\" id=\"delRetailerInput\" list=\"retailerDatalist\" placeholder=\"Type shop name (auto-creates if new)...\" oninput=\"updateLiveDeliveryPreview()\" />\n            <datalist id=\"retailerDatalist\"></datalist>\n          </div>\n          <div class=\"field\">\n            <label>30 kg Bags</label>\n            <input type=\"number\" id=\"delBags\" step=\"1\" min=\"0\" value=\"\" placeholder=\"0\" oninput=\"calcFromBagsLoose()\" />\n            <div class=\"chip-row\">\n              <span class=\"chip\" onclick=\"quickBags(1)\">+1 Bag</span>\n              <span class=\"chip\" onclick=\"quickBags(2)\">+2</span>\n              <span class=\"chip\" onclick=\"quickBags(5)\">+5</span>\n              <span class=\"chip\" onclick=\"quickBags(7)\">+7 (210kg)</span>\n            </div>\n          </div>\n          <div class=\"field\">\n            <label>Loose KG</label>\n            <input type=\"number\" id=\"delLoose\" step=\"0.5\" min=\"0\" value=\"\" placeholder=\"0\" oninput=\"calcFromBagsLoose()\" />\n          </div>\n          <div class=\"field\">\n            <label>Total KG *</label>\n            <input type=\"number\" id=\"delTotalKg\" step=\"0.5\" min=\"0.5\" placeholder=\"Auto or direct KG\" oninput=\"calcFromTotalKg()\" style=\"font-weight:800;color:var(--navy);background:#fffbeb;\" />\n          </div>\n          <div class=\"field\">\n            <label>Remarks / Bill No.</label>\n            <input type=\"text\" id=\"delRemarks\" placeholder=\"Optional bill/note\" />\n          </div>\n          <div class=\"field\" style=\"display:flex;flex-direction:row;gap:8px;\">\n            <button class=\"btn btn-brand\" style=\"flex:1;\" onclick=\"saveDelivery()\" id=\"btnSaveDelivery\">\u2713 Save Delivery</button>\n            <button class=\"btn btn-outline\" id=\"btnCancelEdit\" style=\"display:none;\" onclick=\"resetDeliveryForm()\">Cancel</button>\n          </div>\n        </div>\n\n        <div id=\"liveDelPreview\" style=\"display:none;margin-top:12px;padding:10px 14px;border-radius:10px;background:#f8fafc;border:1px solid var(--border);font-size:13px;\"></div>\n      </div>\n\n      <!-- Delivery Log -->\n      <div class=\"card\">\n        <div class=\"card-header\">\n          <div>\n            <div class=\"card-title\">\ud83d\udcdc Saved Delivery Log</div>\n            <div class=\"card-sub\" id=\"delLogCount\">0 deliveries recorded</div>\n          </div>\n          <div style=\"display:flex;gap:8px;flex-wrap:wrap;\">\n            <input type=\"text\" id=\"delSearch\" placeholder=\"\ud83d\udd0d Search shop or DL-ID...\" oninput=\"renderDeliveries()\" style=\"width:210px;\" />\n            <input type=\"date\" id=\"delFilterDate\" onchange=\"renderDeliveries()\" style=\"width:155px;\" />\n            <button class=\"btn btn-outline btn-sm\" onclick=\"document.getElementById('delFilterDate').value='';document.getElementById('delSearch').value='';renderDeliveries();\">Reset</button>\n          </div>\n        </div>\n        <div class=\"table-wrap\">\n          <table>\n            <thead>\n              <tr>\n                <th>Date</th>\n                <th>Retailer Name</th>\n                <th class=\"num\">30kg Bags</th>\n                <th class=\"num\">Loose KG</th>\n                <th class=\"num\">Total KG</th>\n                <th>Remarks</th>\n                <th>Delivery ID</th>\n                <th>Actions</th>\n              </tr>\n            </thead>\n            <tbody id=\"deliveryTbody\"></tbody>\n          </table>\n        </div>\n      </div>\n    </section>\n\n    <!-- ================= TAB 3: ALLOT COUPONS (EK SATH) ================= -->\n    <section id=\"screen-allot\" class=\"screen\">\n      <!-- 1-Click Bulk Allot Hero -->\n      <div class=\"hero-box\">\n        <div style=\"display:flex;justify-content:space-between;align-items:flex-start;gap:14px;flex-wrap:wrap;\">\n          <div style=\"max-width:680px;\">\n            <div style=\"font-size:18px;font-weight:800;color:#78350f;display:flex;align-items:center;gap:8px;\">\n              \u26a1 Ek Sath Sabhi Pending Coupons Allot Karein (1-Click Bulk Allotment)\n            </div>\n            <p style=\"font-size:13.5px;color:#92400e;margin-top:4px;line-height:1.45;\" id=\"allotHeroDesc\">\n              Jab retailers ke 210 kg ke hisab se coupons pure ho jayein (ya pure 300 coupons complete ho jayein), yahan se ek hi click me sabhi pending coupons ek sath allot karein.\n            </p>\n          </div>\n          <div style=\"display:flex;gap:8px;align-items:center;flex-wrap:wrap;\">\n            <span class=\"badge badge-amber\" style=\"font-size:13px;padding:6px 12px;\" id=\"allotPoolStatusBadge\">Pool: 0 / 300 Allotted</span>\n          </div>\n        </div>\n\n        <div class=\"form-grid\" style=\"margin-top:14px;background:rgba(255,255,255,0.78);padding:14px;border-radius:12px;border:1px solid #fde68a;\">\n          <div class=\"field\">\n            <label>Allotment / Issue Date</label>\n            <input type=\"date\" id=\"bulkIssueDate\" />\n          </div>\n          <div class=\"field\">\n            <label>Coupon Numbering Mode</label>\n            <select id=\"bulkNumberMode\">\n              <option value=\"sequential\">Sequential (Kram se: 001, 002, 003...)</option>\n              <option value=\"random\">Random Lucky Shuffle (Available pool me se random)</option>\n            </select>\n          </div>\n          <div class=\"field\" style=\"grid-column: span 2;\">\n            <button class=\"btn btn-brand\" style=\"width:100%;padding:12px 18px;font-size:14.5px;\" onclick=\"openBulkAllotPreview()\" id=\"btnBulkAllotAll\">\n              \ud83c\udf9f\ufe0f Preview & Allot All Pending Coupons Ek Sath\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <!-- Selective / Retailer-wise Batch Allotment Table -->\n      <div class=\"card\">\n        <div class=\"card-header\">\n          <div>\n            <div class=\"card-title\">\ud83d\udccb Retailer-wise Batch Coupon Allotment</div>\n            <div class=\"card-sub\">Chahein to kisi ek retailer ya chune hue retailers ko custom sankhya me bhi allot kar sakte hain</div>\n          </div>\n          <div style=\"display:flex;gap:8px;align-items:center;\">\n            <button class=\"btn btn-primary btn-sm\" onclick=\"allotSelectedCustomRows()\">\u2713 Allot Entered Quantities</button>\n          </div>\n        </div>\n        <div class=\"table-wrap\">\n          <table>\n            <thead>\n              <tr>\n                <th>Retailer Name</th>\n                <th class=\"num\">Total KG</th>\n                <th class=\"num\">Earned</th>\n                <th class=\"num\">Already Issued</th>\n                <th class=\"num\">Pending</th>\n                <th style=\"width:130px;\">Allot Qty Now</th>\n                <th>Existing Coupons</th>\n                <th>Single Action</th>\n              </tr>\n            </thead>\n            <tbody id=\"batchAllotTbody\"></tbody>\n          </table>\n        </div>\n      </div>\n\n      <!-- Issued Coupons Master Table -->\n      <div class=\"card\">\n        <div class=\"card-header\">\n          <div>\n            <div class=\"card-title\">\ud83c\udf9f\ufe0f Allotted Coupons Register</div>\n            <div class=\"card-sub\" id=\"issuedListSub\">Total 0 coupons allotted</div>\n          </div>\n          <div style=\"display:flex;gap:8px;flex-wrap:wrap;\">\n            <input type=\"text\" id=\"couponSearch\" placeholder=\"\ud83d\udd0d Search Coupon # or Shop...\" oninput=\"renderAllotScreen()\" style=\"width:220px;\" />\n            <button class=\"btn btn-outline btn-sm\" onclick=\"openManualSingleCouponModal()\">+ Manual Coupon # Allot</button>\n          </div>\n        </div>\n        <div class=\"table-wrap\">\n          <table>\n            <thead>\n              <tr>\n                <th>Coupon No.</th>\n                <th>Retailer Name</th>\n                <th>Area / Mobile</th>\n                <th>Issue Date</th>\n                <th>Prize Status</th>\n                <th>Action</th>\n              </tr>\n            </thead>\n            <tbody id=\"issuedCouponsTbody\"></tbody>\n          </table>\n        </div>\n      </div>\n    </section>\n\n    <!-- ================= TAB 4: LUCKY DRAW & PRIZE ENTRY ================= -->\n    <section id=\"screen-prizes\" class=\"screen\">\n      <!-- Quick Prize Winner Entry Card -->\n      <div class=\"card\" style=\"border: 1.5px solid #86efac;\">\n        <div class=\"card-header\">\n          <div>\n            <div class=\"card-title\">\ud83c\udfc6 Lucky Draw Winner & Prize Entry (Prize Chadhayein)</div>\n            <div class=\"card-sub\">Draw nikalne ke baad Coupon No. dalein \u2014 Retailer ka naam apne aap aa jayega, phir Prize save karein</div>\n          </div>\n          <button class=\"btn btn-green btn-sm\" onclick=\"downloadWinnersPDF()\">\ud83d\udcc4 Winners PDF Nikalein</button>\n        </div>\n\n        <div class=\"form-grid\">\n          <div class=\"field\">\n            <label>Winning Coupon No. *</label>\n            <input type=\"text\" id=\"przCouponInput\" list=\"allottedCouponsDatalist\" placeholder=\"e.g. 001 or 45\" oninput=\"lookupWinningCoupon()\" style=\"font-weight:800;font-size:16px;\" />\n            <datalist id=\"allottedCouponsDatalist\"></datalist>\n          </div>\n          <div class=\"field\" style=\"grid-column: span 2;\">\n            <label>Prize Name / Item Won *</label>\n            <input type=\"text\" id=\"przTitleInput\" placeholder=\"e.g. 1st Prize - Maruti Alto Car / LED TV / Mixer\" />\n            <div class=\"chip-row\">\n              <span class=\"chip\" onclick=\"setPrizePreset(1, '1st Mega Prize - Maruti Alto Car')\">\ud83e\udd47 1st: Alto Car</span>\n              <span class=\"chip\" onclick=\"setPrizePreset(2, '2nd Prize')\">\ud83e\udd48 2nd Prize</span>\n              <span class=\"chip\" onclick=\"setPrizePreset(3, '3rd Prize')\">\ud83e\udd49 3rd Prize</span>\n              <span class=\"chip\" onclick=\"setPrizePreset(4, 'LED TV')\">\ud83d\udcfa LED TV</span>\n              <span class=\"chip\" onclick=\"setPrizePreset(5, 'Mixer Grinder')\">\ud83c\udf81 Mixer Grinder</span>\n              <span class=\"chip\" onclick=\"setPrizePreset(10, 'Consolation Prize')\">\u2b50 Consolation</span>\n            </div>\n          </div>\n          <div class=\"field\">\n            <label>Prize Rank (1 = Top)</label>\n            <input type=\"number\" id=\"przRankInput\" min=\"1\" max=\"999\" value=\"1\" />\n          </div>\n          <div class=\"field\">\n            <label>Draw Date</label>\n            <input type=\"date\" id=\"przDrawDate\" />\n          </div>\n          <div class=\"field\">\n            <label>Handover Status</label>\n            <select id=\"przStatusSelect\">\n              <option value=\"WON\">\ud83c\udfc6 Winner Declared</option>\n              <option value=\"DELIVERED\">\u2705 Prize Handed Over</option>\n            </select>\n          </div>\n          <div class=\"field\">\n            <label>Remarks (Optional)</label>\n            <input type=\"text\" id=\"przRemarksInput\" placeholder=\"Stage / Token note\" />\n          </div>\n          <div class=\"field\">\n            <button class=\"btn btn-green\" style=\"width:100%;padding:11px;\" onclick=\"savePrizeFromCard()\">\ud83c\udfc6 Save Winner Prize</button>\n          </div>\n        </div>\n\n        <div id=\"przMatchedBox\" class=\"winner-preview-box\" style=\"display:none;\"></div>\n      </div>\n\n      <!-- Winners List & Fast Inline Register -->\n      <div class=\"card\">\n        <div class=\"card-header\">\n          <div>\n            <div class=\"card-title\">\ud83c\udf89 Prize Register & Fast Table Entry</div>\n            <div class=\"card-sub\">Yahan se direct har coupon ke samne bhi Prize likh kar Save kar sakte hain</div>\n          </div>\n          <div style=\"display:flex;gap:8px;flex-wrap:wrap;\">\n            <input type=\"text\" id=\"przTableSearch\" placeholder=\"\ud83d\udd0d Search Coupon #, Shop or Prize...\" oninput=\"renderPrizeScreen()\" style=\"width:220px;\" />\n            <select id=\"przTableFilter\" onchange=\"renderPrizeScreen()\" style=\"width:185px;\">\n              <option value=\"WINNERS\">\ud83c\udfc6 Winners Only</option>\n              <option value=\"ALL\">All Allotted Coupons</option>\n              <option value=\"UNWON\">Pending / No Prize Yet</option>\n            </select>\n          </div>\n        </div>\n        <div class=\"table-wrap\">\n          <table>\n            <thead>\n              <tr>\n                <th>Rank</th>\n                <th>Coupon No.</th>\n                <th>Retailer Name</th>\n                <th>Area / Mobile</th>\n                <th style=\"min-width:210px;\">Prize Won</th>\n                <th style=\"width:140px;\">Status</th>\n                <th>Save / Clear</th>\n              </tr>\n            </thead>\n            <tbody id=\"prizeRegisterTbody\"></tbody>\n          </table>\n        </div>\n      </div>\n    </section>\n\n    <!-- ================= TAB 5: PDF REPORTS & SETTINGS ================= -->\n    <section id=\"screen-reports\" class=\"screen\">\n      <div class=\"card\">\n        <div class=\"card-header\">\n          <div>\n            <div class=\"card-title\">\ud83d\udcc4 Professional PDF Reports (Download, WhatsApp Share & Print)</div>\n            <div class=\"card-sub\">Sabhi PDF multi-page A4 crisp format me generate hoti hain \u2014 mobile aur PC dono par 1-click download & share</div>\n          </div>\n        </div>\n\n        <div class=\"report-grid\">\n          <!-- Report 1 -->\n          <div class=\"report-card\" style=\"border-color:#86efac;background:#f0fdf4;\">\n            <div>\n              <span class=\"badge badge-green\">Post-Draw Main Report</span>\n              <h3 style=\"font-size:15.5px;margin:8px 0 4px;color:var(--navy);\">\ud83c\udfc6 Final Lucky Draw Prize Winners Report</h3>\n              <p style=\"font-size:12.5px;color:var(--muted);line-height:1.45;\">\n                Draw ke baad jeetne wale sabhi Coupon Numbers, Retailer ka naam, gaon/area, Prize ka naam, Status aur Signatory ke sath official PDF report.\n              </p>\n            </div>\n            <div style=\"display:flex;gap:7px;flex-wrap:wrap;\">\n              <button class=\"btn btn-green btn-sm\" onclick=\"downloadWinnersPDF(false)\">\u2b07\ufe0f Download PDF</button>\n              <button class=\"btn btn-outline btn-sm\" onclick=\"downloadWinnersPDF(true)\">\ud83d\udcf2 WhatsApp Share</button>\n              <button class=\"btn btn-outline btn-sm\" onclick=\"printHTMLReport('WINNERS')\">\ud83d\udda8\ufe0f Print A4</button>\n            </div>\n          </div>\n\n          <!-- Report 2 -->\n          <div class=\"report-card\" style=\"border-color:#fde68a;background:#fffbeb;\">\n            <div>\n              <span class=\"badge badge-amber\">Stage & Audit Sheet</span>\n              <h3 style=\"font-size:15.5px;margin:8px 0 4px;color:var(--navy);\">\ud83d\udccb Complete 300 Coupon & Prize Register</h3>\n              <p style=\"font-size:12.5px;color:var(--muted);line-height:1.45;\">\n                Sheet ke 'Print List' jaisa pura Coupon #001 se #300 register. Draw se pehle khali Prize column ke sath stage ke liye aur draw ke baad bhare hue prizes ke sath!\n              </p>\n            </div>\n            <div style=\"display:flex;gap:7px;flex-wrap:wrap;\">\n              <button class=\"btn btn-brand btn-sm\" onclick=\"downloadFullRegisterPDF(false)\">\u2b07\ufe0f Download PDF</button>\n              <button class=\"btn btn-outline btn-sm\" onclick=\"downloadFullRegisterPDF(true)\">\ud83d\udcf2 WhatsApp Share</button>\n              <button class=\"btn btn-outline btn-sm\" onclick=\"printHTMLReport('REGISTER')\">\ud83d\udda8\ufe0f Print A4</button>\n            </div>\n          </div>\n\n          <!-- Report 3 -->\n          <div class=\"report-card\">\n            <div>\n              <span class=\"badge badge-blue\">Purchase & Ledger</span>\n              <h3 style=\"font-size:15.5px;margin:8px 0 4px;color:var(--navy);\">\ud83c\udfea Retailer Purchase & Coupon Summary</h3>\n              <p style=\"font-size:12.5px;color:var(--muted);line-height:1.45;\">\n                Har dukandar ka kul KG, 30kg Bags, Earned Coupons, Allotted Coupon Numbers aur \u091c\u0940\u0924\u0947 \u0939\u0941\u090f Prizes ka pura hisab.\n              </p>\n            </div>\n            <div style=\"display:flex;gap:7px;flex-wrap:wrap;\">\n              <button class=\"btn btn-primary btn-sm\" onclick=\"downloadRetailerSummaryPDF(false)\">\u2b07\ufe0f Download PDF</button>\n              <button class=\"btn btn-outline btn-sm\" onclick=\"downloadRetailerSummaryPDF(true)\">\ud83d\udcf2 WhatsApp Share</button>\n              <button class=\"btn btn-outline btn-sm\" onclick=\"printHTMLReport('SUMMARY')\">\ud83d\udda8\ufe0f Print A4</button>\n            </div>\n          </div>\n\n          <!-- Report 4 -->\n          <div class=\"report-card\">\n            <div>\n              <span class=\"badge badge-teal\">Handover Receipt</span>\n              <h3 style=\"font-size:15.5px;margin:8px 0 4px;color:var(--navy);\">\ud83c\udf9f\ufe0f Retailer Coupon Handover Slips</h3>\n              <p style=\"font-size:12.5px;color:var(--muted);line-height:1.45;\">\n                Ek sath coupon allot karne ke baad har retailer ko kaun-kaun se coupon number mile uski printable parchi / distribution list.\n              </p>\n            </div>\n            <div style=\"display:flex;gap:7px;flex-wrap:wrap;\">\n              <button class=\"btn btn-outline btn-sm\" onclick=\"downloadHandoverSlipsPDF(false)\">\u2b07\ufe0f Download PDF</button>\n              <button class=\"btn btn-outline btn-sm\" onclick=\"downloadHandoverSlipsPDF(true)\">\ud83d\udcf2 WhatsApp Share</button>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- Scheme Settings & Backup -->\n      <div class=\"card\">\n        <div class=\"card-header\">\n          <div>\n            <div class=\"card-title\">\u2699\ufe0f Scheme Configuration & Data Backup</div>\n            <div class=\"card-sub\">Company title, 210 kg rule, 300 max coupons aur JSON backup manage karein</div>\n          </div>\n        </div>\n        <div class=\"form-grid\">\n          <div class=\"field\">\n            <label>Company Name</label>\n            <input type=\"text\" id=\"setCompany\" value=\"ARYUSH FOODS\" />\n          </div>\n          <div class=\"field\">\n            <label>Campaign / Draw Name</label>\n            <input type=\"text\" id=\"setCampaign\" value=\"MEGA ALTO LUCKY DRAW\" />\n          </div>\n          <div class=\"field\">\n            <label>KG per 1 Coupon</label>\n            <input type=\"number\" id=\"setKgPerCoupon\" value=\"210\" min=\"1\" />\n          </div>\n          <div class=\"field\">\n            <label>KG per 1 Bag</label>\n            <input type=\"number\" id=\"setKgPerBag\" value=\"30\" min=\"1\" />\n          </div>\n          <div class=\"field\">\n            <label>Max Coupons Pool</label>\n            <input type=\"number\" id=\"setMaxCoupons\" value=\"300\" min=\"10\" />\n          </div>\n          <div class=\"field\">\n            <label>Coupon Prefix (Optional, e.g. AF-)</label>\n            <input type=\"text\" id=\"setPrefix\" placeholder=\"Blank = 001, 002...\" />\n          </div>\n          <div class=\"field\">\n            <label>Authorized Signatory Footer</label>\n            <input type=\"text\" id=\"setSignatory\" value=\"For Aryush Foods (Kailaras, Morena)\" />\n          </div>\n          <div class=\"field\">\n            <button class=\"btn btn-primary\" style=\"width:100%;\" onclick=\"saveSettings()\">\ud83d\udcbe Save Settings</button>\n          </div>\n        </div>\n\n        <div style=\"margin-top:18px;padding-top:14px;border-top:1px solid var(--border);display:flex;gap:10px;flex-wrap:wrap;align-items:center;justify-content:space-between;\">\n          <div style=\"display:flex;gap:8px;flex-wrap:wrap;\">\n            <button class=\"btn btn-outline btn-sm\" onclick=\"exportBackupJSON()\">\u2b07\ufe0f Full JSON Backup</button>\n            <label class=\"btn btn-outline btn-sm\" style=\"cursor:pointer;\">\n              \u2b06\ufe0f Restore Backup JSON\n              <input type=\"file\" accept=\".json\" style=\"display:none\" onchange=\"importBackupJSON(event)\" />\n            </label>\n            <button class=\"btn btn-outline btn-sm\" onclick=\"exportDeliveriesCSV()\">\ud83d\udcca Export Deliveries CSV</button>\n          </div>\n          <button class=\"btn btn-outline btn-sm\" onclick=\"openRetailerManageModal()\">\ud83c\udfea Manage Retailers List</button>\n        </div>\n      </div>\n    </section>\n\n  </main>\n\n  <!-- Bottom Mobile Navigation -->\n  <nav class=\"bottom-nav\">\n    <div class=\"bottom-nav-inner\">\n      <button class=\"bnav-btn active\" data-tab=\"overview\" onclick=\"switchTab('overview')\"><span class=\"ico\">\ud83d\udcca</span><span>Overview</span></button>\n      <button class=\"bnav-btn\" data-tab=\"deliveries\" onclick=\"switchTab('deliveries')\"><span class=\"ico\">\ud83d\ude9a</span><span>Delivery</span></button>\n      <button class=\"bnav-btn\" data-tab=\"allot\" onclick=\"switchTab('allot')\"><span class=\"ico\">\ud83c\udf9f\ufe0f</span><span>Allot</span></button>\n      <button class=\"bnav-btn\" data-tab=\"prizes\" onclick=\"switchTab('prizes')\"><span class=\"ico\">\ud83c\udfc6</span><span>Prizes</span></button>\n      <button class=\"bnav-btn\" data-tab=\"reports\" onclick=\"switchTab('reports')\"><span class=\"ico\">\ud83d\udcc4</span><span>PDF</span></button>\n    </div>\n  </nav>\n\n  <!-- Print Container -->\n  <div id=\"printSection\"></div>\n\n  <!-- Toast -->\n  <div id=\"toast\"></div>\n\n  <!-- MODAL 1: Add / Manage Retailer -->\n  <div class=\"modal-backdrop\" id=\"retailerModal\">\n    <div class=\"modal\" style=\"max-width:500px;\">\n      <div class=\"modal-head\">\n        <h3 style=\"font-size:16px;font-weight:800;\">\ud83c\udfea Add New Retailer</h3>\n        <button class=\"btn btn-outline btn-sm\" onclick=\"closeModal('retailerModal')\">\u2715</button>\n      </div>\n      <div style=\"display:flex;flex-direction:column;gap:11px;\">\n        <div class=\"field\">\n          <label>Retailer / Shop Name *</label>\n          <input type=\"text\" id=\"modRetName\" placeholder=\"e.g. POOJA KIRANA BAZAR FARAK\" />\n        </div>\n        <div class=\"field\">\n          <label>Area / Village / Market</label>\n          <input type=\"text\" id=\"modRetArea\" placeholder=\"e.g. Kailaras / Dongarpur\" />\n        </div>\n        <div class=\"field\">\n          <label>Mobile Number</label>\n          <input type=\"tel\" id=\"modRetPhone\" placeholder=\"10-digit mobile (optional)\" />\n        </div>\n        <button class=\"btn btn-brand\" onclick=\"createRetailerFromModal()\">\u2713 Save Retailer</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- MODAL 2: Manage All Retailers -->\n  <div class=\"modal-backdrop\" id=\"retailerManageModal\">\n    <div class=\"modal\">\n      <div class=\"modal-head\">\n        <h3 style=\"font-size:16px;font-weight:800;\">\ud83c\udfea Manage Retailers</h3>\n        <button class=\"btn btn-outline btn-sm\" onclick=\"closeModal('retailerManageModal')\">\u2715</button>\n      </div>\n      <div class=\"table-wrap\" style=\"max-height:60vh;overflow-y:auto;\">\n        <table style=\"min-width:450px;\">\n          <thead><tr><th>Shop Name</th><th>Area</th><th>Mobile</th><th>Action</th></tr></thead>\n          <tbody id=\"manageRetTbody\"></tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n\n  <!-- MODAL 3: Bulk Allot Preview Modal -->\n  <div class=\"modal-backdrop\" id=\"bulkAllotModal\">\n    <div class=\"modal\">\n      <div class=\"modal-head\">\n        <h3 style=\"font-size:16.5px;font-weight:800;\">\ud83c\udf9f\ufe0f Confirm Ek Sath Coupon Allotment</h3>\n        <button class=\"btn btn-outline btn-sm\" onclick=\"closeModal('bulkAllotModal')\">\u2715</button>\n      </div>\n      <p id=\"bulkPreviewSummary\" style=\"font-size:13.5px;color:var(--muted);margin-bottom:12px;\"></p>\n      <div class=\"table-wrap\" style=\"max-height:52vh;overflow-y:auto;margin-bottom:14px;\">\n        <table style=\"min-width:420px;\">\n          <thead>\n            <tr><th>Retailer Name</th><th class=\"num\">Total KG</th><th class=\"num\">Coupons to Allot</th></tr>\n          </thead>\n          <tbody id=\"bulkPreviewTbody\"></tbody>\n        </table>\n      </div>\n      <div style=\"display:flex;justify-content:flex-end;gap:10px;\">\n        <button class=\"btn btn-outline\" onclick=\"closeModal('bulkAllotModal')\">Cancel</button>\n        <button class=\"btn btn-brand\" id=\"btnConfirmBulkNow\" onclick=\"executeBulkAllotNow()\">\u26a1 Confirm & Allot Ek Sath</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- MODAL 4: Manual Single Coupon Allot -->\n  <div class=\"modal-backdrop\" id=\"manualCouponModal\">\n    <div class=\"modal\" style=\"max-width:460px;\">\n      <div class=\"modal-head\">\n        <h3 style=\"font-size:16px;font-weight:800;\">\ud83c\udf9f\ufe0f Manual Specific Coupon # Allot</h3>\n        <button class=\"btn btn-outline btn-sm\" onclick=\"closeModal('manualCouponModal')\">\u2715</button>\n      </div>\n      <div style=\"display:flex;flex-direction:column;gap:11px;\">\n        <div class=\"field\">\n          <label>Select Retailer *</label>\n          <select id=\"manCupRetailer\"></select>\n        </div>\n        <div class=\"field\">\n          <label>Specific Coupon Number (1 to <span id=\"lblMaxCupModal\">300</span>) *</label>\n          <input type=\"number\" id=\"manCupNumber\" min=\"1\" placeholder=\"e.g. 51\" />\n        </div>\n        <div class=\"field\">\n          <label>Issue Date</label>\n          <input type=\"date\" id=\"manCupDate\" />\n        </div>\n        <button class=\"btn btn-primary\" onclick=\"saveManualSingleCoupon()\">\u2713 Allot Coupon Number</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- MODAL 5: Bulk Paste from Google Sheet -->\n  <div class=\"modal-backdrop\" id=\"bulkImportModal\">\n    <div class=\"modal\">\n      <div class=\"modal-head\">\n        <h3 style=\"font-size:16px;font-weight:800;\">\ud83d\udccb Bulk Paste from Google Sheet</h3>\n        <button class=\"btn btn-outline btn-sm\" onclick=\"closeModal('bulkImportModal')\">\u2715</button>\n      </div>\n      <p style=\"font-size:12.5px;color:var(--muted);margin-bottom:10px;line-height:1.45;\">\n        Apni Google Sheet se seedha rows copy karke yahan paste karein:<br/>\n        \u2022 <b>Sirf Retailers ke naam</b> (ek line me ek dukaan ka naam), YA<br/>\n        \u2022 <b>Delivery Log rows</b>: <code>Date [Tab] Retailer Name [Tab] Total KG</code> (ya <code>Date [Tab] Retailer [Tab] Bags [Tab] Loose KG</code>)\n      </p>\n      <div class=\"field\" style=\"margin-bottom:10px;\">\n        <label>Import Type</label>\n        <select id=\"importTypeSelect\">\n          <option value=\"DELIVERIES\">\ud83d\ude9a Deliveries (Date, Retailer, Total KG) \u2014 Tab/Comma separated</option>\n          <option value=\"RETAILERS\">\ud83c\udfea Only Retailer Names (1 shop per line)</option>\n        </select>\n      </div>\n      <div class=\"field\" style=\"margin-bottom:12px;\">\n        <textarea id=\"bulkPasteArea\" rows=\"7\" placeholder=\"2026-11-07&#9;POOJA KIRANA BAZAR FARAK&#9;30&#10;2026-11-15&#9;GOYAL PROVIJAN DONGARPUR&#9;210\"></textarea>\n      </div>\n      <div style=\"display:flex;justify-content:flex-end;gap:8px;\">\n        <button class=\"btn btn-outline\" onclick=\"closeModal('bulkImportModal')\">Cancel</button>\n        <button class=\"btn btn-brand\" onclick=\"processBulkPaste()\">\u2b06\ufe0f Import Now</button>\n      </div>\n    </div>\n  </div>\n\n<script>\n  // ================= STATE & CONFIG =================\n  const IS_LOCAL_PREVIEW = (window.location.protocol === 'file:' || window.FORCE_LOCAL_MODE === true);\n  let STATE = {\n    settings: {\n      company_name: 'ARYUSH FOODS',\n      campaign_name: 'MEGA ALTO LUCKY DRAW',\n      kg_per_coupon: 210,\n      kg_per_bag: 30,\n      max_coupons: 300,\n      coupon_prefix: '',\n      signatory: 'For Aryush Foods (Kailaras, Morena)'\n    },\n    retailers: [],\n    deliveries: [],\n    coupons: [],\n    summaryRows: []\n  };\n\n  function todayISO() {\n    const d = new Date();\n    const tzOffset = d.getTimezoneOffset() * 60000;\n    return new Date(d.getTime() - tzOffset).toISOString().slice(0, 10);\n  }\n\n  function formatDateDisplay(iso) {\n    if (!iso) return '-';\n    const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];\n    const parts = String(iso).slice(0,10).split('-');\n    if (parts.length !== 3) return iso;\n    const m = parseInt(parts[1], 10) - 1;\n    return `${parts[2]}-${months[m] || parts[1]}-${parts[0]}`;\n  }\n\n  function padCouponNum(num) {\n    const maxC = Number(STATE.settings.max_coupons) || 300;\n    const digits = maxC >= 1000 ? 4 : 3;\n    const prefix = STATE.settings.coupon_prefix || '';\n    return prefix + String(num).padStart(digits, '0');\n  }\n\n  function toast(msg, isError = false) {\n    const el = document.getElementById('toast');\n    el.textContent = msg;\n    el.style.background = isError ? '#dc2626' : '#0f172a';\n    el.style.display = 'block';\n    clearTimeout(window._toastTimer);\n    window._toastTimer = setTimeout(() => { el.style.display = 'none'; }, 3200);\n  }\n\n  function esc(str) {\n    return String(str ?? '').replace(/[&<>\"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[m]));\n  }\n\n  // ================= API / LOCAL STORAGE ADAPTER =================\n  const LOCAL_KEY = 'aryush_lucky_draw_local_v1';\n\n  function loadLocalDB() {\n    try {\n      const raw = localStorage.getItem(LOCAL_KEY);\n      if (raw) return JSON.parse(raw);\n    } catch (e) {}\n    return {\n      settings: { ...STATE.settings },\n      retailers: [],\n      deliveries: [],\n      coupons: [],\n      seq: { retailer: 1, delivery: 1, coupon: 1 }\n    };\n  }\n\n  function saveLocalDB(db) {\n    localStorage.setItem(LOCAL_KEY, JSON.stringify(db));\n  }\n\n  async function apiCall(path, method = 'GET', body = null) {\n    if (!IS_LOCAL_PREVIEW) {\n      try {\n        const opts = { method, headers: { 'Content-Type': 'application/json' } };\n        if (body) opts.body = JSON.stringify(body);\n        const res = await fetch(path, opts);\n        const data = await res.json();\n        if (!res.ok || data.error) throw new Error(data.error || 'Server error');\n        return data;\n      } catch (err) {\n        if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') {\n          throw err;\n        }\n        throw err;\n      }\n    }\n\n    // LocalStorage Mock Engine (for standalone-preview.html offline testing)\n    const db = loadLocalDB();\n    if (path === '/api/bootstrap' && method === 'GET') {\n      return { settings: db.settings, retailers: db.retailers, deliveries: db.deliveries, coupons: db.coupons };\n    }\n    if (path === '/api/settings' && method === 'POST') {\n      db.settings = { ...db.settings, ...body };\n      saveLocalDB(db);\n      return { ok: true, settings: db.settings };\n    }\n    if (path === '/api/retailers' && method === 'POST') {\n      const name = String(body.name || '').trim().toUpperCase();\n      if (!name) throw new Error('Retailer name required');\n      let existing = db.retailers.find(r => r.name.toUpperCase() === name);\n      if (existing) {\n        existing.area = body.area ?? existing.area;\n        existing.phone = body.phone ?? existing.phone;\n        saveLocalDB(db);\n        return { ok: true, retailer: existing };\n      }\n      const r = { id: db.seq.retailer++, name, area: String(body.area||'').trim(), phone: String(body.phone||'').trim() };\n      db.retailers.push(r);\n      saveLocalDB(db);\n      return { ok: true, retailer: r };\n    }\n    if (path.startsWith('/api/retailers/') && method === 'DELETE') {\n      const id = Number(path.split('/').pop());\n      db.retailers = db.retailers.filter(r => r.id !== id);\n      db.deliveries = db.deliveries.filter(d => d.retailer_id !== id);\n      db.coupons = db.coupons.filter(c => c.retailer_id !== id);\n      saveLocalDB(db);\n      return { ok: true };\n    }\n    if (path === '/api/deliveries' && method === 'POST') {\n      const rName = String(body.retailer_name || '').trim().toUpperCase();\n      let ret = db.retailers.find(r => r.id === Number(body.retailer_id)) || db.retailers.find(r => r.name.toUpperCase() === rName);\n      if (!ret) {\n        if (!rName) throw new Error('Select or enter retailer');\n        ret = { id: db.seq.retailer++, name: rName, area: '', phone: '' };\n        db.retailers.push(ret);\n      }\n      if (body.id) {\n        const idx = db.deliveries.findIndex(d => d.id === Number(body.id));\n        if (idx === -1) throw new Error('Delivery not found');\n        db.deliveries[idx] = {\n          ...db.deliveries[idx],\n          entry_date: body.entry_date,\n          retailer_id: ret.id,\n          bags: Number(body.bags) || 0,\n          loose_kg: Number(body.loose_kg) || 0,\n          total_kg: Number(body.total_kg) || 0,\n          remarks: String(body.remarks || '')\n        };\n      } else {\n        const dl_code = 'DL-' + Math.random().toString(16).slice(2, 10).toUpperCase();\n        db.deliveries.unshift({\n          id: db.seq.delivery++,\n          dl_code,\n          entry_date: body.entry_date,\n          retailer_id: ret.id,\n          bags: Number(body.bags) || 0,\n          loose_kg: Number(body.loose_kg) || 0,\n          total_kg: Number(body.total_kg) || 0,\n          remarks: String(body.remarks || '')\n        });\n      }\n      saveLocalDB(db);\n      return { ok: true };\n    }\n    if (path.startsWith('/api/deliveries/') && method === 'DELETE') {\n      const id = Number(path.split('/').pop());\n      db.deliveries = db.deliveries.filter(d => d.id !== id);\n      saveLocalDB(db);\n      return { ok: true };\n    }\n    if (path === '/api/coupons/allot' && method === 'POST') {\n      const maxC = Number(db.settings.max_coupons) || 300;\n      const prefix = db.settings.coupon_prefix || '';\n      const digits = maxC >= 1000 ? 4 : 3;\n      const usedSet = new Set(db.coupons.map(c => Number(c.coupon_num)));\n\n      if (body.manual_coupon_num) {\n        const num = Number(body.manual_coupon_num);\n        if (num < 1 || num > maxC) throw new Error(`Coupon number must be between 1 and ${maxC}`);\n        if (usedSet.has(num)) throw new Error(`Coupon #${num} is already allotted!`);\n        db.coupons.push({\n          id: db.seq.coupon++,\n          coupon_num: num,\n          coupon_code: prefix + String(num).padStart(digits, '0'),\n          retailer_id: Number(body.retailer_id),\n          issue_date: body.issue_date || todayISO(),\n          batch_ref: 'MANUAL',\n          prize_rank: 999, prize_title: '', prize_value: 0, draw_date: '', prize_status: 'NONE', remarks: ''\n        });\n        saveLocalDB(db);\n        return { ok: true, allotted: 1 };\n      }\n\n      const items = body.allocations || [];\n      const totalNeeded = items.reduce((s, x) => s + (Number(x.count) || 0), 0);\n      const available = [];\n      for (let i = 1; i <= maxC; i++) if (!usedSet.has(i)) available.push(i);\n      if (totalNeeded > available.length) {\n        throw new Error(`Only ${available.length} coupons left in pool, cannot allot ${totalNeeded}. Increase Max Coupons in Settings if needed.`);\n      }\n      if (body.mode === 'random') {\n        for (let i = available.length - 1; i > 0; i--) {\n          const j = Math.floor(Math.random() * (i + 1));\n          [available[i], available[j]] = [available[j], available[i]];\n        }\n      }\n      let ptr = 0;\n      const batchRef = 'BATCH-' + Date.now().toString(36).toUpperCase();\n      for (const item of items) {\n        const cnt = Number(item.count) || 0;\n        for (let k = 0; k < cnt; k++) {\n          const num = available[ptr++];\n          db.coupons.push({\n            id: db.seq.coupon++,\n            coupon_num: num,\n            coupon_code: prefix + String(num).padStart(digits, '0'),\n            retailer_id: Number(item.retailer_id),\n            issue_date: body.issue_date || todayISO(),\n            batch_ref: batchRef,\n            prize_rank: 999, prize_title: '', prize_value: 0, draw_date: '', prize_status: 'NONE', remarks: ''\n          });\n        }\n      }\n      saveLocalDB(db);\n      return { ok: true, allotted: totalNeeded };\n    }\n    if (path.startsWith('/api/coupons/') && method === 'DELETE') {\n      const id = Number(path.split('/').pop());\n      db.coupons = db.coupons.filter(c => c.id !== id);\n      saveLocalDB(db);\n      return { ok: true };\n    }\n    if (path === '/api/coupons/prize' && method === 'POST') {\n      const c = db.coupons.find(x => x.id === Number(body.coupon_id) || x.coupon_num === Number(body.coupon_num));\n      if (!c) throw new Error('Coupon not found');\n      c.prize_title = String(body.prize_title || '').trim();\n      c.prize_rank = c.prize_title ? (Number(body.prize_rank) || 99) : 999;\n      c.draw_date = body.draw_date || todayISO();\n      c.prize_status = c.prize_title ? (body.prize_status || 'WON') : 'NONE';\n      c.remarks = String(body.remarks || '');\n      saveLocalDB(db);\n      return { ok: true };\n    }\n    if (path === '/api/import' && method === 'POST') {\n      if (body.full_restore) {\n        saveLocalDB({\n          settings: body.settings || db.settings,\n          retailers: body.retailers || [],\n          deliveries: body.deliveries || [],\n          coupons: body.coupons || [],\n          seq: { retailer: 5000, delivery: 50000, coupon: 50000 }\n        });\n        return { ok: true };\n      }\n      for (const name of (body.retailers || [])) {\n        const clean = String(name).trim().toUpperCase();\n        if (clean && !db.retailers.find(r => r.name.toUpperCase() === clean)) {\n          db.retailers.push({ id: db.seq.retailer++, name: clean, area: '', phone: '' });\n        }\n      }\n      for (const d of (body.deliveries || [])) {\n        const clean = String(d.retailer_name || '').trim().toUpperCase();\n        if (!clean) continue;\n        let ret = db.retailers.find(r => r.name.toUpperCase() === clean);\n        if (!ret) {\n          ret = { id: db.seq.retailer++, name: clean, area: '', phone: '' };\n          db.retailers.push(ret);\n        }\n        db.deliveries.push({\n          id: db.seq.delivery++,\n          dl_code: 'DL-' + Math.random().toString(16).slice(2, 10).toUpperCase(),\n          entry_date: d.entry_date || todayISO(),\n          retailer_id: ret.id,\n          bags: Number(d.bags) || 0,\n          loose_kg: Number(d.loose_kg) || 0,\n          total_kg: Number(d.total_kg) || 0,\n          remarks: d.remarks || ''\n        });\n      }\n      saveLocalDB(db);\n      return { ok: true };\n    }\n    throw new Error('Unknown route');\n  }\n\n  // ================= COMPUTE SUMMARY ENGINE =================\n  function computeDerivedState() {\n    const kgPerCup = Math.max(1, Number(STATE.settings.kg_per_coupon) || 210);\n    const kgPerBag = Math.max(1, Number(STATE.settings.kg_per_bag) || 30);\n\n    const retMap = new Map();\n    for (const r of STATE.retailers) {\n      retMap.set(r.id, {\n        ...r,\n        total_kg: 0,\n        equiv_bags: 0,\n        earned: 0,\n        issued: 0,\n        pending: 0,\n        next_rem_kg: 0,\n        next_pct: 0,\n        coupons: [],\n        prizes: []\n      });\n    }\n\n    for (const d of STATE.deliveries) {\n      const r = retMap.get(d.retailer_id);\n      if (r) r.total_kg = Math.round((r.total_kg + (Number(d.total_kg) || 0)) * 100) / 100;\n    }\n\n    const sortedCoupons = [...STATE.coupons].sort((a, b) => a.coupon_num - b.coupon_num);\n    for (const c of sortedCoupons) {\n      const r = retMap.get(c.retailer_id);\n      if (r) {\n        r.coupons.push(c);\n        if (c.prize_status !== 'NONE' && c.prize_title) r.prizes.push(c);\n      }\n    }\n\n    const rows = [];\n    for (const r of retMap.values()) {\n      r.equiv_bags = Math.round((r.total_kg / kgPerBag) * 100) / 100;\n      r.earned = Math.floor((r.total_kg + 1e-9) / kgPerCup);\n      r.issued = r.coupons.length;\n      r.pending = Math.max(0, r.earned - r.issued);\n      const rem = Math.round((r.total_kg % kgPerCup) * 100) / 100;\n      r.next_rem_kg = rem;\n      r.next_pct = Math.min(100, Math.round((rem / kgPerCup) * 100));\n      rows.push(r);\n    }\n\n    rows.sort((a, b) => b.total_kg - a.total_kg || a.name.localeCompare(b.name));\n    STATE.summaryRows = rows;\n  }\n\n  async function refreshAll() {\n    try {\n      const data = await apiCall('/api/bootstrap');\n      STATE.settings = { ...STATE.settings, ...(data.settings || {}) };\n      STATE.retailers = data.retailers || [];\n      STATE.deliveries = data.deliveries || [];\n      STATE.coupons = data.coupons || [];\n\n      const badge = document.getElementById('syncBadge');\n      const syncTxt = document.getElementById('syncText');\n      if (IS_LOCAL_PREVIEW) {\n        badge.className = 'sync-pill local';\n        syncTxt.textContent = 'Local Preview Mode';\n      } else {\n        badge.className = 'sync-pill';\n        syncTxt.textContent = 'Cloudflare D1 Live';\n      }\n\n      computeDerivedState();\n      renderHeaderAndSettings();\n      renderOverview();\n      renderDeliveries();\n      renderAllotScreen();\n      renderPrizeScreen();\n    } catch (err) {\n      toast('Error loading data: ' + err.message, true);\n    }\n  }\n\n  function switchTab(tab) {\n    document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));\n    document.getElementById('screen-' + tab).classList.add('active');\n    document.querySelectorAll('.tab-btn, .bnav-btn').forEach(b => {\n      b.classList.toggle('active', b.dataset.tab === tab);\n    });\n    window.scrollTo({ top: 0, behavior: 'smooth' });\n  }\n\n  function renderHeaderAndSettings() {\n    const s = STATE.settings;\n    document.getElementById('hdrCompany').textContent = `${s.company_name} \u2014 ${s.campaign_name}`;\n    document.getElementById('hdrSub').textContent = `1 Coupon per ${s.kg_per_coupon} kg (${Math.round((s.kg_per_coupon / s.kg_per_bag)*10)/10} Bags \u00d7 ${s.kg_per_bag} kg) \u2022 Pool: ${s.max_coupons} Coupons`;\n    document.querySelectorAll('.lblBagKg').forEach(el => el.textContent = s.kg_per_bag);\n    document.querySelectorAll('.lblCouponKg').forEach(el => el.textContent = s.kg_per_coupon);\n    document.getElementById('lblMaxCupModal').textContent = s.max_coupons;\n\n    document.getElementById('setCompany').value = s.company_name || '';\n    document.getElementById('setCampaign').value = s.campaign_name || '';\n    document.getElementById('setKgPerCoupon').value = s.kg_per_coupon || 210;\n    document.getElementById('setKgPerBag').value = s.kg_per_bag || 30;\n    document.getElementById('setMaxCoupons').value = s.max_coupons || 300;\n    document.getElementById('setPrefix').value = s.coupon_prefix || '';\n    document.getElementById('setSignatory').value = s.signatory || '';\n\n    // Datalist for retailers\n    const dl = document.getElementById('retailerDatalist');\n    dl.innerHTML = STATE.retailers.map(r => `<option value=\"${esc(r.name)}\">${esc(r.area || '')}</option>`).join('');\n  }\n\n  // ================= RENDER 1: OVERVIEW =================\n  function renderOverview() {\n    const s = STATE.settings;\n    const maxC = Number(s.max_coupons) || 300;\n    const totalKg = STATE.summaryRows.reduce((a, r) => a + r.total_kg, 0);\n    const totalEarned = STATE.summaryRows.reduce((a, r) => a + r.earned, 0);\n    const totalIssued = STATE.coupons.length;\n    const totalPending = STATE.summaryRows.reduce((a, r) => a + r.pending, 0);\n    const available = Math.max(0, maxC - totalIssued);\n    const activeBuyers = STATE.summaryRows.filter(r => r.total_kg > 0).length;\n    const winnersCount = STATE.coupons.filter(c => c.prize_status !== 'NONE' && c.prize_title).length;\n\n    document.getElementById('kpiTotalKg').textContent = `${Math.round(totalKg * 100) / 100} kg`;\n    document.getElementById('kpiTotalBags').textContent = `${Math.round((totalKg / (s.kg_per_bag || 30)) * 10) / 10} Bags (${s.kg_per_bag} kg)`;\n    document.getElementById('kpiEarned').textContent = totalEarned;\n    document.getElementById('kpiEarnedSub').textContent = `Target: ${s.kg_per_coupon} kg / coupon`;\n    document.getElementById('kpiIssued').textContent = totalIssued;\n    document.getElementById('kpiPoolPct').textContent = `${Math.min(100, Math.round((totalIssued / maxC) * 100))}% of ${maxC} pool`;\n    document.getElementById('kpiPending').textContent = totalPending;\n    document.getElementById('kpiAvailable').textContent = available;\n    document.getElementById('kpiRetailerCount').textContent = `${activeBuyers} Retailers buying`;\n    document.getElementById('kpiWinners').textContent = winnersCount;\n\n    const navBadge = document.getElementById('navPendingBadge');\n    if (totalPending > 0) {\n      navBadge.style.display = 'inline-block';\n      navBadge.textContent = totalPending;\n    } else {\n      navBadge.style.display = 'none';\n    }\n\n    const earnedPct = Math.min(100, Math.round((totalEarned / maxC) * 100));\n    document.getElementById('poolProgBar').style.width = earnedPct + '%';\n    document.getElementById('poolBannerTitle').textContent =\n      totalEarned >= maxC\n        ? `\ud83c\udf89 Target Complete! ${totalEarned} / ${maxC} Coupons Pure Ho Chuke Hain!`\n        : `Scheme Coupon Pool Progress: ${totalEarned} Earned / ${totalIssued} Allotted (Pool: ${maxC})`;\n\n    const q = document.getElementById('sumSearch').value.trim().toLowerCase();\n    const flt = document.getElementById('sumFilter').value;\n    const nearThreshold = (Number(s.kg_per_coupon) || 210) * 0.7;\n\n    const filtered = STATE.summaryRows.filter(r => {\n      if (q && !r.name.toLowerCase().includes(q) && !(r.area || '').toLowerCase().includes(q)) return false;\n      if (flt === 'PENDING' && r.pending <= 0) return false;\n      if (flt === 'EARNED' && r.earned <= 0) return false;\n      if (flt === 'NEAR' && r.next_rem_kg < nearThreshold) return false;\n      if (flt === 'WINNERS' && r.prizes.length === 0) return false;\n      return true;\n    });\n\n    const tbody = document.getElementById('summaryTbody');\n    if (filtered.length === 0) {\n      tbody.innerHTML = `<tr><td colspan=\"10\" style=\"text-align:center;padding:28px;color:var(--muted);\">Abhi koi retailer entry nahi hai. 'New Delivery' ya '+ Add Retailer' se shuru karein.</td></tr>`;\n      return;\n    }\n\n    tbody.innerHTML = filtered.map((r, i) => {\n      const cList = r.coupons.map(c => c.prize_title ? `<span class=\"badge badge-green\" title=\"${esc(c.prize_title)}\">#${esc(c.coupon_code)} \ud83c\udfc6</span>` : `<span class=\"badge badge-gray\">#${esc(c.coupon_code)}</span>`).join(' ');\n      const needMore = Math.round(((s.kg_per_coupon || 210) - r.next_rem_kg) * 100) / 100;\n      return `<tr>\n        <td>${i + 1}</td>\n        <td>\n          <div style=\"font-weight:700;color:var(--navy);\">${esc(r.name)}</div>\n          ${r.area || r.phone ? `<div style=\"font-size:11.5px;color:var(--muted);\">${esc(r.area)}${r.area && r.phone ? ' \u2022 ' : ''}${esc(r.phone)}</div>` : ''}\n        </td>\n        <td class=\"num\">${r.equiv_bags}</td>\n        <td class=\"num\" style=\"font-weight:800;\">${r.total_kg} kg</td>\n        <td style=\"min-width:155px;\">\n          <div style=\"display:flex;justify-content:space-between;font-size:11.5px;color:var(--muted);\">\n            <span>${r.next_rem_kg} / ${s.kg_per_coupon} kg</span>\n            <span>Need ${needMore} kg</span>\n          </div>\n          <div class=\"prog-track\"><div class=\"prog-fill\" style=\"width:${r.next_pct}%\"></div></div>\n        </td>\n        <td class=\"num\"><span class=\"badge badge-teal\">${r.earned}</span></td>\n        <td class=\"num\"><span class=\"badge badge-blue\">${r.issued}</span></td>\n        <td class=\"num\">${r.pending > 0 ? `<span class=\"badge badge-amber\">${r.pending} Pending</span>` : `<span style=\"color:#94a3b8;\">0</span>`}</td>\n        <td style=\"max-width:230px;\">${cList || '<span style=\"color:#94a3b8;font-size:12px;\">Not allotted yet</span>'}</td>\n        <td>\n          <button class=\"btn btn-outline btn-sm\" onclick=\"quickStartDeliveryFor('${esc(r.name)}')\">+ Delivery</button>\n        </td>\n      </tr>`;\n    }).join('');\n  }\n\n  function quickStartDeliveryFor(name) {\n    switchTab('deliveries');\n    document.getElementById('delRetailerInput').value = name;\n    document.getElementById('delBags').focus();\n    updateLiveDeliveryPreview();\n  }\n\n  // ================= RENDER 2: DELIVERIES =================\n  function calcFromBagsLoose() {\n    const bagKg = Number(STATE.settings.kg_per_bag) || 30;\n    const bags = Number(document.getElementById('delBags').value) || 0;\n    const loose = Number(document.getElementById('delLoose').value) || 0;\n    const total = Math.round(((bags * bagKg) + loose) * 100) / 100;\n    document.getElementById('delTotalKg').value = total > 0 ? total : '';\n    updateLiveDeliveryPreview();\n  }\n\n  function calcFromTotalKg() {\n    const bagKg = Number(STATE.settings.kg_per_bag) || 30;\n    const total = Number(document.getElementById('delTotalKg').value) || 0;\n    const bags = Math.floor(total / bagKg);\n    const loose = Math.round((total - bags * bagKg) * 100) / 100;\n    document.getElementById('delBags').value = bags > 0 ? bags : '';\n    document.getElementById('delLoose').value = loose > 0 ? loose : '';\n    updateLiveDeliveryPreview();\n  }\n\n  function quickBags(n) {\n    const cur = Number(document.getElementById('delBags').value) || 0;\n    document.getElementById('delBags').value = cur + n;\n    calcFromBagsLoose();\n  }\n\n  function updateLiveDeliveryPreview() {\n    const box = document.getElementById('liveDelPreview');\n    const name = document.getElementById('delRetailerInput').value.trim().toUpperCase();\n    const addKg = Number(document.getElementById('delTotalKg').value) || 0;\n    if (!name && !addKg) { box.style.display = 'none'; return; }\n\n    const editId = Number(document.getElementById('editDeliveryId').value) || 0;\n    const existingRow = STATE.summaryRows.find(r => r.name.toUpperCase() === name);\n    let prevKg = existingRow ? existingRow.total_kg : 0;\n    if (editId) {\n      const oldDel = STATE.deliveries.find(d => d.id === editId);\n      if (oldDel && existingRow && oldDel.retailer_id === existingRow.id) {\n        prevKg = Math.max(0, prevKg - (Number(oldDel.total_kg) || 0));\n      }\n    }\n    const newTotal = Math.round((prevKg + addKg) * 100) / 100;\n    const cupKg = Number(STATE.settings.kg_per_coupon) || 210;\n    const oldCoupons = Math.floor((prevKg + 1e-9) / cupKg);\n    const newCoupons = Math.floor((newTotal + 1e-9) / cupKg);\n    const diff = newCoupons - oldCoupons;\n\n    box.style.display = 'block';\n    box.innerHTML = `\ud83c\udfea <b>${esc(name || 'New Retailer')}</b>: Pehle ka KG: <b>${prevKg} kg</b> + Is Entry ka: <b>${addKg} kg</b> = Naya Total: <b>${newTotal} kg</b> &nbsp;|&nbsp; Total Earned Coupons: <span class=\"badge badge-teal\">${newCoupons}</span> ${diff > 0 ? `<span class=\"badge badge-green\">\ud83c\udf89 +${diff} New Coupon Completed!</span>` : ''}`;\n  }\n\n  async function saveDelivery() {\n    const entry_date = document.getElementById('delDate').value || todayISO();\n    const retailer_name = document.getElementById('delRetailerInput').value.trim().toUpperCase();\n    const bags = Number(document.getElementById('delBags').value) || 0;\n    const loose_kg = Number(document.getElementById('delLoose').value) || 0;\n    const total_kg = Number(document.getElementById('delTotalKg').value) || 0;\n    const remarks = document.getElementById('delRemarks').value.trim();\n    const id = document.getElementById('editDeliveryId').value;\n\n    if (!retailer_name) return toast('Please enter or select Retailer Name', true);\n    if (total_kg <= 0) return toast('Please enter Bags or Total KG (> 0)', true);\n\n    const btn = document.getElementById('btnSaveDelivery');\n    btn.disabled = true;\n    try {\n      await apiCall('/api/deliveries', 'POST', {\n        id: id ? Number(id) : null,\n        entry_date, retailer_name, bags, loose_kg, total_kg, remarks\n      });\n      toast(id ? 'Delivery updated!' : `Saved ${total_kg} kg for ${retailer_name}`);\n      resetDeliveryForm();\n      await refreshAll();\n    } catch (e) {\n      toast(e.message, true);\n    } finally {\n      btn.disabled = false;\n    }\n  }\n\n  function editDelivery(id) {\n    const d = STATE.deliveries.find(x => x.id === id);\n    if (!d) return;\n    const ret = STATE.retailers.find(r => r.id === d.retailer_id);\n    document.getElementById('editDeliveryId').value = d.id;\n    document.getElementById('delDate').value = d.entry_date;\n    document.getElementById('delRetailerInput').value = ret ? ret.name : '';\n    document.getElementById('delBags').value = d.bags || '';\n    document.getElementById('delLoose').value = d.loose_kg || '';\n    document.getElementById('delTotalKg').value = d.total_kg || '';\n    document.getElementById('delRemarks').value = d.remarks || '';\n    document.getElementById('delFormTitle').textContent = `\u270f\ufe0f Edit Delivery (${d.dl_code})`;\n    document.getElementById('btnSaveDelivery').textContent = '\u2713 Update Changes';\n    document.getElementById('btnCancelEdit').style.display = 'inline-flex';\n    updateLiveDeliveryPreview();\n    window.scrollTo({ top: 0, behavior: 'smooth' });\n  }\n\n  function resetDeliveryForm() {\n    document.getElementById('editDeliveryId').value = '';\n    document.getElementById('delDate').value = todayISO();\n    document.getElementById('delRetailerInput').value = '';\n    document.getElementById('delBags').value = '';\n    document.getElementById('delLoose').value = '';\n    document.getElementById('delTotalKg').value = '';\n    document.getElementById('delRemarks').value = '';\n    document.getElementById('delFormTitle').textContent = '\ud83d\ude9a New Delivery Entry';\n    document.getElementById('btnSaveDelivery').textContent = '\u2713 Save Delivery';\n    document.getElementById('btnCancelEdit').style.display = 'none';\n    document.getElementById('liveDelPreview').style.display = 'none';\n  }\n\n  async function deleteDelivery(id) {\n    if (!confirm('Delete this delivery entry? Retailer total KG will recalculate automatically.')) return;\n    try {\n      await apiCall('/api/deliveries/' + id, 'DELETE');\n      toast('Delivery deleted');\n      await refreshAll();\n    } catch (e) {\n      toast(e.message, true);\n    }\n  }\n\n  function renderDeliveries() {\n    const q = document.getElementById('delSearch').value.trim().toLowerCase();\n    const fDate = document.getElementById('delFilterDate').value;\n    const retById = new Map(STATE.retailers.map(r => [r.id, r]));\n\n    const list = STATE.deliveries.filter(d => {\n      const rName = (retById.get(d.retailer_id)?.name || '').toLowerCase();\n      if (fDate && d.entry_date !== fDate) return false;\n      if (q && !rName.includes(q) && !(d.dl_code || '').toLowerCase().includes(q) && !(d.remarks || '').toLowerCase().includes(q)) return false;\n      return true;\n    });\n\n    document.getElementById('delLogCount').textContent = `${list.length} deliveries shown (Total: ${STATE.deliveries.length})`;\n    const tbody = document.getElementById('deliveryTbody');\n    if (list.length === 0) {\n      tbody.innerHTML = `<tr><td colspan=\"8\" style=\"text-align:center;padding:24px;color:var(--muted);\">No delivery entries found.</td></tr>`;\n      return;\n    }\n\n    tbody.innerHTML = list.map(d => {\n      const rName = retById.get(d.retailer_id)?.name || 'Unknown';\n      return `<tr>\n        <td>${formatDateDisplay(d.entry_date)}</td>\n        <td style=\"font-weight:700;\">${esc(rName)}</td>\n        <td class=\"num\">${d.bags || 0}</td>\n        <td class=\"num\">${d.loose_kg || 0}</td>\n        <td class=\"num\" style=\"font-weight:800;color:var(--navy);\">${d.total_kg} kg</td>\n        <td>${esc(d.remarks || '-')}</td>\n        <td><span class=\"badge badge-gray\">${esc(d.dl_code)}</span></td>\n        <td>\n          <div style=\"display:flex;gap:6px;\">\n            <button class=\"btn btn-outline btn-sm\" onclick=\"editDelivery(${d.id})\">\u270f\ufe0f Edit</button>\n            <button class=\"btn btn-danger btn-sm\" onclick=\"deleteDelivery(${d.id})\">\ud83d\uddd1\ufe0f</button>\n          </div>\n        </td>\n      </tr>`;\n    }).join('');\n  }\n\n  // ================= RENDER 3: ALLOT COUPONS EK SATH =================\n  function renderAllotScreen() {\n    const maxC = Number(STATE.settings.max_coupons) || 300;\n    const issued = STATE.coupons.length;\n    const pendingRows = STATE.summaryRows.filter(r => r.pending > 0);\n    const totalPending = pendingRows.reduce((s, r) => s + r.pending, 0);\n\n    document.getElementById('allotPoolStatusBadge').textContent = `Pool: ${issued} / ${maxC} Allotted (${Math.max(0, maxC - issued)} Left)`;\n    document.getElementById('btnBulkAllotAll').textContent =\n      totalPending > 0\n        ? `\ud83c\udf9f\ufe0f Allot All ${totalPending} Pending Coupons Ek Sath (${pendingRows.length} Retailers)`\n        : `\u2713 Sabhi Earned Coupons Allot Ho Chuke Hain (0 Pending)`;\n    document.getElementById('btnBulkAllotAll').disabled = (totalPending === 0);\n\n    // Batch Allotment Table (all retailers with earned > 0 or issued > 0)\n    const relevant = STATE.summaryRows.filter(r => r.earned > 0 || r.issued > 0);\n    const batchTbody = document.getElementById('batchAllotTbody');\n    if (relevant.length === 0) {\n      batchTbody.innerHTML = `<tr><td colspan=\"8\" style=\"text-align:center;padding:24px;color:var(--muted);\">Abhi kisi retailer ke 210 kg pure nahi hue hain. Delivery chadhane par earned coupons yahan dikhenge.</td></tr>`;\n    } else {\n      batchTbody.innerHTML = relevant.map(r => {\n        const codes = r.coupons.map(c => '#' + c.coupon_code).join(', ');\n        return `<tr>\n          <td style=\"font-weight:700;\">${esc(r.name)}</td>\n          <td class=\"num\">${r.total_kg} kg</td>\n          <td class=\"num\"><span class=\"badge badge-teal\">${r.earned}</span></td>\n          <td class=\"num\"><span class=\"badge badge-blue\">${r.issued}</span></td>\n          <td class=\"num\">${r.pending > 0 ? `<span class=\"badge badge-amber\">${r.pending}</span>` : '0'}</td>\n          <td>\n            <input type=\"number\" class=\"custom-allot-inp\" data-retid=\"${r.id}\" min=\"0\" max=\"${r.pending}\" value=\"${r.pending}\" ${r.pending === 0 ? 'disabled' : ''} style=\"padding:6px 10px;\" />\n          </td>\n          <td style=\"font-size:12px;color:var(--muted);max-width:220px;\">${esc(codes || '-')}</td>\n          <td>\n            ${r.pending > 0 ? `<button class=\"btn btn-brand btn-sm\" onclick=\"allotSingleRetailerPending(${r.id}, ${r.pending})\">Allot ${r.pending}</button>` : '<span class=\"badge badge-green\">\u2713 Done</span>'}\n          </td>\n        </tr>`;\n      }).join('');\n    }\n\n    // Issued Coupons Register\n    const q = document.getElementById('couponSearch').value.trim().toLowerCase();\n    const retById = new Map(STATE.retailers.map(r => [r.id, r]));\n    const sorted = [...STATE.coupons].sort((a, b) => a.coupon_num - b.coupon_num).filter(c => {\n      const r = retById.get(c.retailer_id);\n      if (!q) return true;\n      return c.coupon_code.toLowerCase().includes(q) || (r?.name || '').toLowerCase().includes(q);\n    });\n\n    document.getElementById('issuedListSub').textContent = `Showing ${sorted.length} of ${STATE.coupons.length} allotted coupons`;\n    const cTbody = document.getElementById('issuedCouponsTbody');\n    if (sorted.length === 0) {\n      cTbody.innerHTML = `<tr><td colspan=\"6\" style=\"text-align:center;padding:24px;color:var(--muted);\">No allotted coupons yet.</td></tr>`;\n    } else {\n      cTbody.innerHTML = sorted.map(c => {\n        const r = retById.get(c.retailer_id);\n        return `<tr>\n          <td><span class=\"badge badge-navy\" style=\"background:var(--navy);color:#fbbf24;font-size:13px;\">#${esc(c.coupon_code)}</span></td>\n          <td style=\"font-weight:700;\">${esc(r?.name || '-')}</td>\n          <td style=\"color:var(--muted);font-size:12.5px;\">${esc(r?.area || '')} ${esc(r?.phone || '')}</td>\n          <td>${formatDateDisplay(c.issue_date)}</td>\n          <td>${c.prize_title ? `<span class=\"badge badge-green\">\ud83c\udfc6 ${esc(c.prize_title)}</span>` : '<span style=\"color:#94a3b8;font-size:12px;\">-</span>'}</td>\n          <td><button class=\"btn btn-danger btn-sm\" onclick=\"revokeCoupon(${c.id}, '${esc(c.coupon_code)}')\">Revoke</button></td>\n        </tr>`;\n      }).join('');\n    }\n  }\n\n  function openBulkAllotPreview() {\n    const pendingRows = STATE.summaryRows.filter(r => r.pending > 0);\n    if (pendingRows.length === 0) return toast('No pending coupons to allot!', true);\n    const totalPending = pendingRows.reduce((s, r) => s + r.pending, 0);\n    const mode = document.getElementById('bulkNumberMode').value;\n    const dt = document.getElementById('bulkIssueDate').value || todayISO();\n\n    document.getElementById('bulkPreviewSummary').innerHTML =\n      `Issue Date: <b>${formatDateDisplay(dt)}</b> &nbsp;|&nbsp; Mode: <b>${mode === 'random' ? 'Random Lucky Shuffle' : 'Sequential (001, 002...)'}</b> &nbsp;|&nbsp; Total: <b>${totalPending} Coupons</b> across <b>${pendingRows.length} Retailers</b>`;\n\n    document.getElementById('bulkPreviewTbody').innerHTML = pendingRows.map(r => `\n      <tr>\n        <td style=\"font-weight:700;\">${esc(r.name)}</td>\n        <td class=\"num\">${r.total_kg} kg</td>\n        <td class=\"num\"><span class=\"badge badge-amber\">${r.pending} Coupons</span></td>\n      </tr>\n    `).join('');\n    openModal('bulkAllotModal');\n  }\n\n  async function executeBulkAllotNow() {\n    const pendingRows = STATE.summaryRows.filter(r => r.pending > 0);\n    const allocations = pendingRows.map(r => ({ retailer_id: r.id, count: r.pending }));\n    const issue_date = document.getElementById('bulkIssueDate').value || todayISO();\n    const mode = document.getElementById('bulkNumberMode').value;\n\n    const btn = document.getElementById('btnConfirmBulkNow');\n    btn.disabled = true;\n    try {\n      const res = await apiCall('/api/coupons/allot', 'POST', { allocations, issue_date, mode });\n      closeModal('bulkAllotModal');\n      toast(`\ud83c\udf89 Successfully allotted ${res.allotted} coupons ek sath!`);\n      await refreshAll();\n    } catch (e) {\n      toast(e.message, true);\n    } finally {\n      btn.disabled = false;\n    }\n  }\n\n  async function allotSelectedCustomRows() {\n    const inputs = Array.from(document.querySelectorAll('.custom-allot-inp:not(:disabled)'));\n    const allocations = inputs\n      .map(inp => ({ retailer_id: Number(inp.dataset.retid), count: Number(inp.value) || 0 }))\n      .filter(x => x.count > 0);\n    if (allocations.length === 0) return toast('Enter at least 1 coupon quantity to allot', true);\n    const issue_date = document.getElementById('bulkIssueDate').value || todayISO();\n    const mode = document.getElementById('bulkNumberMode').value;\n    try {\n      const res = await apiCall('/api/coupons/allot', 'POST', { allocations, issue_date, mode });\n      toast(`Allotted ${res.allotted} coupons!`);\n      await refreshAll();\n    } catch (e) {\n      toast(e.message, true);\n    }\n  }\n\n  async function allotSingleRetailerPending(retailer_id, count) {\n    const issue_date = document.getElementById('bulkIssueDate').value || todayISO();\n    const mode = document.getElementById('bulkNumberMode').value;\n    try {\n      await apiCall('/api/coupons/allot', 'POST', {\n        allocations: [{ retailer_id, count }],\n        issue_date, mode\n      });\n      toast(`Allotted ${count} coupon(s)!`);\n      await refreshAll();\n    } catch (e) {\n      toast(e.message, true);\n    }\n  }\n\n  function openManualSingleCouponModal() {\n    if (STATE.retailers.length === 0) return toast('Add a retailer first', true);\n    document.getElementById('manCupRetailer').innerHTML = STATE.retailers\n      .map(r => `<option value=\"${r.id}\">${esc(r.name)}</option>`).join('');\n    document.getElementById('manCupDate').value = todayISO();\n    document.getElementById('manCupNumber').value = '';\n    openModal('manualCouponModal');\n  }\n\n  async function saveManualSingleCoupon() {\n    const retailer_id = Number(document.getElementById('manCupRetailer').value);\n    const manual_coupon_num = Number(document.getElementById('manCupNumber').value);\n    const issue_date = document.getElementById('manCupDate').value || todayISO();\n    if (!manual_coupon_num) return toast('Enter coupon number', true);\n    try {\n      await apiCall('/api/coupons/allot', 'POST', { retailer_id, manual_coupon_num, issue_date });\n      closeModal('manualCouponModal');\n      toast(`Coupon #${padCouponNum(manual_coupon_num)} allotted!`);\n      await refreshAll();\n    } catch (e) {\n      toast(e.message, true);\n    }\n  }\n\n  async function revokeCoupon(id, code) {\n    if (!confirm(`Revoke / un-allot Coupon #${code}?`)) return;\n    try {\n      await apiCall('/api/coupons/' + id, 'DELETE');\n      toast(`Coupon #${code} revoked`);\n      await refreshAll();\n    } catch (e) {\n      toast(e.message, true);\n    }\n  }\n\n  // ================= RENDER 4: PRIZE ENTRY & DRAW =================\n  function findCouponByInput(raw) {\n    const clean = String(raw || '').trim().replace(/^#/, '');\n    if (!clean) return null;\n    const asNum = Number(clean.replace(/[^0-9]/g, ''));\n    return STATE.coupons.find(c =>\n      c.coupon_code.toLowerCase() === clean.toLowerCase() ||\n      (asNum > 0 && c.coupon_num === asNum)\n    ) || null;\n  }\n\n  function lookupWinningCoupon() {\n    const val = document.getElementById('przCouponInput').value;\n    const box = document.getElementById('przMatchedBox');\n    if (!val.trim()) { box.style.display = 'none'; return; }\n    const c = findCouponByInput(val);\n    box.style.display = 'block';\n    if (!c) {\n      box.style.background = '#fee2e2';\n      box.style.borderColor = '#fca5a5';\n      box.innerHTML = `\u26a0\ufe0f <b>Coupon Not Found / Not Allotted Yet!</b> Kripya allotted coupon number check karein.`;\n      return;\n    }\n    const r = STATE.summaryRows.find(x => x.id === c.retailer_id);\n    box.style.background = 'linear-gradient(135deg, #ecfdf5 0%, #d1fae5 100%)';\n    box.style.borderColor = '#6ee7b7';\n    box.innerHTML = `\u2705 Matched Coupon <b>#${esc(c.coupon_code)}</b> &rarr; \ud83c\udfea <b style=\"font-size:15px;\">${esc(r?.name || 'Unknown')}</b> ${r?.area ? `(${esc(r.area)})` : ''} ${r?.phone ? `\u2022 \ud83d\udcde ${esc(r.phone)}` : ''} \u2022 Purchase: <b>${r?.total_kg || 0} kg</b> ${c.prize_title ? `<span class=\"badge badge-amber\">Existing Prize: ${esc(c.prize_title)}</span>` : ''}`;\n    if (c.prize_title && !document.getElementById('przTitleInput').value) {\n      document.getElementById('przTitleInput').value = c.prize_title;\n      document.getElementById('przRankInput').value = c.prize_rank < 999 ? c.prize_rank : 1;\n    }\n  }\n\n  function setPrizePreset(rank, title) {\n    document.getElementById('przRankInput').value = rank;\n    document.getElementById('przTitleInput').value = title;\n  }\n\n  async function savePrizeFromCard() {\n    const rawCup = document.getElementById('przCouponInput').value;\n    const c = findCouponByInput(rawCup);\n    if (!c) return toast('Valid allotted Coupon No. dalein!', true);\n    const prize_title = document.getElementById('przTitleInput').value.trim();\n    if (!prize_title) return toast('Prize ka naam likhein!', true);\n    const prize_rank = Number(document.getElementById('przRankInput').value) || 99;\n    const draw_date = document.getElementById('przDrawDate').value || todayISO();\n    const prize_status = document.getElementById('przStatusSelect').value;\n    const remarks = document.getElementById('przRemarksInput').value.trim();\n\n    try {\n      await apiCall('/api/coupons/prize', 'POST', {\n        coupon_id: c.id, prize_title, prize_rank, draw_date, prize_status, remarks\n      });\n      toast(`\ud83c\udfc6 Saved Prize \"${prize_title}\" on Coupon #${c.coupon_code}!`);\n      document.getElementById('przCouponInput').value = '';\n      document.getElementById('przTitleInput').value = '';\n      document.getElementById('przRemarksInput').value = '';\n      document.getElementById('przMatchedBox').style.display = 'none';\n      document.getElementById('przTableFilter').value = 'WINNERS';\n      await refreshAll();\n    } catch (e) {\n      toast(e.message, true);\n    }\n  }\n\n  async function saveInlinePrize(couponId) {\n    const title = document.getElementById('inPrzTitle_' + couponId).value.trim();\n    const rank = Number(document.getElementById('inPrzRank_' + couponId).value) || 99;\n    const status = document.getElementById('inPrzStat_' + couponId).value;\n    try {\n      await apiCall('/api/coupons/prize', 'POST', {\n        coupon_id: couponId,\n        prize_title: title,\n        prize_rank: title ? rank : 999,\n        draw_date: todayISO(),\n        prize_status: title ? status : 'NONE',\n        remarks: ''\n      });\n      toast(title ? 'Prize saved!' : 'Prize cleared');\n      await refreshAll();\n    } catch (e) {\n      toast(e.message, true);\n    }\n  }\n\n  function renderPrizeScreen() {\n    const retById = new Map(STATE.retailers.map(r => [r.id, r]));\n    const dl = document.getElementById('allottedCouponsDatalist');\n    dl.innerHTML = [...STATE.coupons]\n      .sort((a, b) => a.coupon_num - b.coupon_num)\n      .map(c => `<option value=\"${esc(c.coupon_code)}\">${esc(retById.get(c.retailer_id)?.name || '')}</option>`).join('');\n\n    const q = document.getElementById('przTableSearch').value.trim().toLowerCase();\n    const flt = document.getElementById('przTableFilter').value;\n\n    let list = [...STATE.coupons];\n    if (flt === 'WINNERS') list = list.filter(c => c.prize_status !== 'NONE' && c.prize_title);\n    if (flt === 'UNWON') list = list.filter(c => !c.prize_title || c.prize_status === 'NONE');\n\n    if (q) {\n      list = list.filter(c => {\n        const r = retById.get(c.retailer_id);\n        return c.coupon_code.toLowerCase().includes(q) ||\n          (r?.name || '').toLowerCase().includes(q) ||\n          (c.prize_title || '').toLowerCase().includes(q);\n      });\n    }\n\n    list.sort((a, b) => {\n      if (flt === 'WINNERS') return (a.prize_rank || 999) - (b.prize_rank || 999) || a.coupon_num - b.coupon_num;\n      return a.coupon_num - b.coupon_num;\n    });\n\n    const tbody = document.getElementById('prizeRegisterTbody');\n    if (list.length === 0) {\n      tbody.innerHTML = `<tr><td colspan=\"7\" style=\"text-align:center;padding:26px;color:var(--muted);\">${flt === 'WINNERS' ? 'Abhi koi prize winner add nahi hua hai. Upar Coupon No. daal kar prize chadhayein ya filter \"All Allotted Coupons\" chunein.' : 'No matching coupons found.'}</td></tr>`;\n      return;\n    }\n\n    tbody.innerHTML = list.map(c => {\n      const r = retById.get(c.retailer_id);\n      return `<tr>\n        <td style=\"width:72px;\">\n          <input type=\"number\" id=\"inPrzRank_${c.id}\" value=\"${c.prize_rank < 999 ? c.prize_rank : ''}\" placeholder=\"#\" style=\"padding:6px 8px;width:64px;\" />\n        </td>\n        <td><span class=\"badge\" style=\"background:var(--navy);color:#fbbf24;font-size:13px;\">#${esc(c.coupon_code)}</span></td>\n        <td style=\"font-weight:700;\">${esc(r?.name || '-')}</td>\n        <td style=\"font-size:12px;color:var(--muted);\">${esc(r?.area || '')} ${esc(r?.phone || '')}</td>\n        <td>\n          <input type=\"text\" id=\"inPrzTitle_${c.id}\" value=\"${esc(c.prize_title || '')}\" placeholder=\"Enter Prize Won...\" style=\"padding:6px 10px;\" />\n        </td>\n        <td>\n          <select id=\"inPrzStat_${c.id}\" style=\"padding:6px 8px;\">\n            <option value=\"WON\" ${c.prize_status === 'WON' ? 'selected' : ''}>Declared</option>\n            <option value=\"DELIVERED\" ${c.prize_status === 'DELIVERED' ? 'selected' : ''}>Handed Over \u2705</option>\n          </select>\n        </td>\n        <td>\n          <button class=\"btn btn-green btn-sm\" onclick=\"saveInlinePrize(${c.id})\">Save</button>\n        </td>\n      </tr>`;\n    }).join('');\n  }\n\n  // ================= RETAILERS, SETTINGS & IMPORT =================\n  function openModal(id) { document.getElementById(id).classList.add('open'); }\n  function closeModal(id) { document.getElementById(id).classList.remove('open'); }\n\n  function openRetailerModal() {\n    document.getElementById('modRetName').value = '';\n    document.getElementById('modRetArea').value = '';\n    document.getElementById('modRetPhone').value = '';\n    openModal('retailerModal');\n  }\n\n  async function createRetailerFromModal() {\n    const name = document.getElementById('modRetName').value.trim().toUpperCase();\n    const area = document.getElementById('modRetArea').value.trim();\n    const phone = document.getElementById('modRetPhone').value.trim();\n    if (!name) return toast('Enter shop name', true);\n    try {\n      await apiCall('/api/retailers', 'POST', { name, area, phone });\n      closeModal('retailerModal');\n      toast(`Retailer \"${name}\" saved!`);\n      await refreshAll();\n    } catch (e) {\n      toast(e.message, true);\n    }\n  }\n\n  function openRetailerManageModal() {\n    const tbody = document.getElementById('manageRetTbody');\n    tbody.innerHTML = STATE.retailers.map(r => `\n      <tr>\n        <td style=\"font-weight:700;\">${esc(r.name)}</td>\n        <td>${esc(r.area || '-')}</td>\n        <td>${esc(r.phone || '-')}</td>\n        <td><button class=\"btn btn-danger btn-sm\" onclick=\"deleteRetailer(${r.id}, '${esc(r.name)}')\">Delete</button></td>\n      </tr>\n    `).join('') || '<tr><td colspan=\"4\" style=\"text-align:center;padding:18px;\">No retailers</td></tr>';\n    openModal('retailerManageModal');\n  }\n\n  async function deleteRetailer(id, name) {\n    if (!confirm(`Delete retailer \"${name}\" and all their deliveries/coupons?`)) return;\n    try {\n      await apiCall('/api/retailers/' + id, 'DELETE');\n      toast('Retailer deleted');\n      await refreshAll();\n      openRetailerManageModal();\n    } catch (e) {\n      toast(e.message, true);\n    }\n  }\n\n  async function saveSettings() {\n    const payload = {\n      company_name: document.getElementById('setCompany').value.trim() || 'ARYUSH FOODS',\n      campaign_name: document.getElementById('setCampaign').value.trim() || 'MEGA ALTO LUCKY DRAW',\n      kg_per_coupon: Math.max(1, Number(document.getElementById('setKgPerCoupon').value) || 210),\n      kg_per_bag: Math.max(1, Number(document.getElementById('setKgPerBag').value) || 30),\n      max_coupons: Math.max(1, Number(document.getElementById('setMaxCoupons').value) || 300),\n      coupon_prefix: document.getElementById('setPrefix').value.trim(),\n      signatory: document.getElementById('setSignatory').value.trim()\n    };\n    try {\n      await apiCall('/api/settings', 'POST', payload);\n      toast('Settings saved successfully!');\n      await refreshAll();\n    } catch (e) {\n      toast(e.message, true);\n    }\n  }\n\n  function openBulkImportModal() {\n    document.getElementById('bulkPasteArea').value = '';\n    openModal('bulkImportModal');\n  }\n\n  function normalizeSheetDate(raw) {\n    const s = String(raw || '').trim();\n    if (/^\\d{4}-\\d{2}-\\d{2}$/.test(s)) return s;\n    const parsed = new Date(s);\n    if (!isNaN(parsed.getTime())) {\n      const tz = parsed.getTimezoneOffset() * 60000;\n      return new Date(parsed.getTime() - tz).toISOString().slice(0, 10);\n    }\n    return todayISO();\n  }\n\n  async function processBulkPaste() {\n    const type = document.getElementById('importTypeSelect').value;\n    const raw = document.getElementById('bulkPasteArea').value.trim();\n    if (!raw) return toast('Paste data first!', true);\n    const lines = raw.split(/\\r?\\n/).map(l => l.trim()).filter(Boolean);\n\n    try {\n      if (type === 'RETAILERS') {\n        await apiCall('/api/import', 'POST', { retailers: lines });\n        toast(`Imported ${lines.length} retailers!`);\n      } else {\n        const bagKg = Number(STATE.settings.kg_per_bag) || 30;\n        const deliveries = [];\n        for (const line of lines) {\n          const cols = line.includes('\\t') ? line.split('\\t') : line.split(',');\n          if (cols.length < 2) continue;\n          if (cols[0].toLowerCase().includes('date') || cols[1].toLowerCase().includes('retailer')) continue;\n          const entry_date = normalizeSheetDate(cols[0]);\n          const retailer_name = cols[1].trim().toUpperCase();\n          let bags = 0, loose_kg = 0, total_kg = 0;\n          if (cols.length >= 4 && !isNaN(Number(cols[2])) && !isNaN(Number(cols[3]))) {\n            bags = Number(cols[2]) || 0;\n            loose_kg = Number(cols[3]) || 0;\n            total_kg = (bags * bagKg) + loose_kg;\n          } else {\n            total_kg = parseFloat(String(cols[2] || '0').replace(/[^0-9.]/g, '')) || 0;\n            bags = Math.floor(total_kg / bagKg);\n            loose_kg = Math.round((total_kg - bags * bagKg) * 100) / 100;\n          }\n          if (retailer_name && total_kg > 0) {\n            deliveries.push({ entry_date, retailer_name, bags, loose_kg, total_kg });\n          }\n        }\n        if (deliveries.length === 0) return toast('No valid delivery rows detected. Format: Date [Tab] Shop [Tab] Total KG', true);\n        await apiCall('/api/import', 'POST', { deliveries });\n        toast(`Imported ${deliveries.length} deliveries!`);\n      }\n      closeModal('bulkImportModal');\n      await refreshAll();\n    } catch (e) {\n      toast(e.message, true);\n    }\n  }\n\n  function exportBackupJSON() {\n    const blob = new Blob([JSON.stringify({\n      exported_at: new Date().toISOString(),\n      settings: STATE.settings,\n      retailers: STATE.retailers,\n      deliveries: STATE.deliveries,\n      coupons: STATE.coupons\n    }, null, 2)], { type: 'application/json' });\n    const a = document.createElement('a');\n    a.href = URL.createObjectURL(blob);\n    a.download = `Aryush_Lucky_Draw_Backup_${todayISO()}.json`;\n    a.click();\n  }\n\n  async function importBackupJSON(ev) {\n    const file = ev.target.files[0];\n    if (!file) return;\n    if (!confirm('Restore backup? Current data will be replaced with backup file data.')) return;\n    const text = await file.text();\n    try {\n      const parsed = JSON.parse(text);\n      await apiCall('/api/import', 'POST', { full_restore: true, ...parsed });\n      toast('Backup restored successfully!');\n      await refreshAll();\n    } catch (e) {\n      toast('Invalid backup JSON: ' + e.message, true);\n    }\n  }\n\n  function exportDeliveriesCSV() {\n    const retById = new Map(STATE.retailers.map(r => [r.id, r.name]));\n    const rows = [['Date', 'Retailer Name', 'Bags', 'Loose KG', 'Total KG', 'Delivery ID', 'Remarks']];\n    for (const d of STATE.deliveries) {\n      rows.push([d.entry_date, `\"${(retById.get(d.retailer_id)||'').replace(/\"/g,'\"\"')}\"`, d.bags, d.loose_kg, d.total_kg, d.dl_code, `\"${(d.remarks||'').replace(/\"/g,'\"\"')}\"`]);\n    }\n    const csv = rows.map(r => r.join(',')).join('\\n');\n    const blob = new Blob([csv], { type: 'text/csv' });\n    const a = document.createElement('a');\n    a.href = URL.createObjectURL(blob);\n    a.download = `Aryush_Deliveries_${todayISO()}.csv`;\n    a.click();\n  }\n\n  // ================= VECTOR PDF ENGINE (jsPDF + AutoTable + WhatsApp Share) =================\n  function pdfSafeText(str) {\n    return String(str ?? '').replace(/\u20b9/g, 'Rs. ');\n  }\n\n  async function finishPDF(doc, filename, shareViaWhatsApp = false) {\n    if (shareViaWhatsApp && navigator.canShare) {\n      try {\n        const blob = doc.output('blob');\n        const file = new File([blob], filename, { type: 'application/pdf' });\n        if (navigator.canShare({ files: [file] })) {\n          await navigator.share({\n            title: filename.replace(/_/g, ' '),\n            text: `${STATE.settings.company_name} - ${STATE.settings.campaign_name}`,\n            files: [file]\n          });\n          return;\n        }\n      } catch (err) {\n        if (err.name === 'AbortError') return;\n      }\n    }\n    doc.save(filename);\n    toast(`PDF Ready: ${filename}`);\n  }\n\n  function drawPDFHeader(doc, reportTitle, subtitleLine) {\n    const s = STATE.settings;\n    const pageW = doc.internal.pageSize.getWidth();\n    doc.setFillColor(15, 23, 42);\n    doc.rect(0, 0, pageW, 28, 'F');\n\n    doc.setTextColor(251, 191, 36);\n    doc.setFont('helvetica', 'bold');\n    doc.setFontSize(15);\n    doc.text(pdfSafeText(`${s.company_name} | ${s.campaign_name}`), 14, 11);\n\n    doc.setTextColor(255, 255, 255);\n    doc.setFontSize(11);\n    doc.text(pdfSafeText(reportTitle), 14, 18.5);\n\n    doc.setFont('helvetica', 'normal');\n    doc.setFontSize(8.5);\n    doc.setTextColor(203, 213, 225);\n    doc.text(pdfSafeText(subtitleLine), 14, 24.5);\n  }\n\n  function addPageFooters(doc) {\n    const pageCount = doc.internal.getNumberOfPages();\n    const pageW = doc.internal.pageSize.getWidth();\n    const pageH = doc.internal.pageSize.getHeight();\n    const sig = pdfSafeText(STATE.settings.signatory || 'Authorized Signatory');\n\n    for (let i = 1; i <= pageCount; i++) {\n      doc.setPage(i);\n      doc.setFontSize(8.5);\n      doc.setTextColor(100, 116, 139);\n      doc.text(`Generated on ${formatDateDisplay(todayISO())} | ${sig}`, 14, pageH - 8);\n      doc.text(`Page ${i} of ${pageCount}`, pageW - 32, pageH - 8);\n    }\n  }\n\n  // 1. Winners Prize Report PDF\n  async function downloadWinnersPDF(share = false) {\n    if (!window.jspdf) return printHTMLReport('WINNERS');\n    const { jsPDF } = window.jspdf;\n    const doc = new jsPDF('p', 'mm', 'a4');\n    const retById = new Map(STATE.summaryRows.map(r => [r.id, r]));\n\n    const winners = [...STATE.coupons]\n      .filter(c => c.prize_status !== 'NONE' && c.prize_title)\n      .sort((a, b) => (a.prize_rank || 999) - (b.prize_rank || 999) || a.coupon_num - b.coupon_num);\n\n    drawPDFHeader(\n      doc,\n      'OFFICIAL LUCKY DRAW PRIZE WINNERS REPORT',\n      `Total Coupons Allotted: ${STATE.coupons.length} / ${STATE.settings.max_coupons}  |  Total Winners Declared: ${winners.length}  |  Date: ${formatDateDisplay(todayISO())}`\n    );\n\n    const body = winners.length > 0\n      ? winners.map((c, idx) => {\n          const r = retById.get(c.retailer_id);\n          return [\n            c.prize_rank < 999 ? `#${c.prize_rank}` : String(idx + 1),\n            `#${pdfSafeText(c.coupon_code)}`,\n            pdfSafeText(r?.name || '-'),\n            pdfSafeText([r?.area, r?.phone].filter(Boolean).join(' | ') || '-'),\n            pdfSafeText(c.prize_title),\n            c.prize_status === 'DELIVERED' ? 'Handed Over' : 'Winner Declared',\n            formatDateDisplay(c.draw_date || c.issue_date)\n          ];\n        })\n      : [['-', '-', 'No winners entered yet', '-', '-', '-', '-']];\n\n    doc.autoTable({\n      startY: 33,\n      head: [['Rank', 'Coupon No.', 'Winning Retailer Name', 'Area / Mobile', 'Prize Won', 'Status', 'Date']],\n      body,\n      theme: 'grid',\n      headStyles: { fillColor: [15, 23, 42], textColor: [251, 191, 36], fontStyle: 'bold', fontSize: 9 },\n      bodyStyles: { fontSize: 8.8, textColor: [15, 23, 42] },\n      alternateRowStyles: { fillColor: [248, 250, 252] },\n      columnStyles: {\n        0: { cellWidth: 14, halign: 'center', fontStyle: 'bold' },\n        1: { cellWidth: 23, fontStyle: 'bold' },\n        4: { fontStyle: 'bold', textColor: [21, 128, 61] }\n      },\n      margin: { bottom: 18 }\n    });\n\n    const finalY = Math.min(doc.lastAutoTable.finalY + 18, 268);\n    doc.setFontSize(9.5);\n    doc.setTextColor(15, 23, 42);\n    doc.text('_______________________________', 135, finalY);\n    doc.text(pdfSafeText(STATE.settings.signatory || 'Authorized Signatory'), 135, finalY + 5);\n\n    addPageFooters(doc);\n    await finishPDF(doc, `Aryush_Lucky_Draw_Winners_${todayISO()}.pdf`, share);\n  }\n\n  // 2. Full 300 Coupon & Prize Register PDF (matches Print List tab!)\n  async function downloadFullRegisterPDF(share = false) {\n    if (!window.jspdf) return printHTMLReport('REGISTER');\n    const { jsPDF } = window.jspdf;\n    const doc = new jsPDF('p', 'mm', 'a4');\n    const retById = new Map(STATE.summaryRows.map(r => [r.id, r]));\n    const maxC = Number(STATE.settings.max_coupons) || 300;\n    const byNum = new Map(STATE.coupons.map(c => [Number(c.coupon_num), c]));\n\n    drawPDFHeader(\n      doc,\n      'COMPLETE COUPON & PRIZE REGISTER',\n      `1 Coupon per ${STATE.settings.kg_per_coupon} kg  |  Allotted: ${STATE.coupons.length} of ${maxC}  |  Blank Prize rows for live manual draw entry`\n    );\n\n    const rows = [];\n    for (let n = 1; n <= maxC; n++) {\n      const c = byNum.get(n);\n      const r = c ? retById.get(c.retailer_id) : null;\n      rows.push([\n        `#${padCouponNum(n)}`,\n        c ? pdfSafeText(r?.name || '-') : '(Unallotted)',\n        c ? pdfSafeText(r?.area || '-') : '-',\n        c ? formatDateDisplay(c.issue_date) : '-',\n        c && c.prize_title ? pdfSafeText(c.prize_title) : ''\n      ]);\n    }\n\n    doc.autoTable({\n      startY: 33,\n      head: [['Coupon No.', 'Retailer Name', 'Area / Village', 'Issue Date', 'Prize Won']],\n      body: rows,\n      theme: 'grid',\n      headStyles: { fillColor: [15, 23, 42], textColor: [251, 191, 36], fontStyle: 'bold', fontSize: 9 },\n      bodyStyles: { fontSize: 8.5, minCellHeight: 7.5 },\n      alternateRowStyles: { fillColor: [248, 250, 252] },\n      columnStyles: {\n        0: { cellWidth: 24, fontStyle: 'bold' },\n        1: { cellWidth: 68 },\n        2: { cellWidth: 32 },\n        3: { cellWidth: 26 },\n        4: { cellWidth: 36, fontStyle: 'bold' }\n      },\n      margin: { bottom: 15 }\n    });\n\n    addPageFooters(doc);\n    await finishPDF(doc, `Aryush_Coupon_Prize_Register_${todayISO()}.pdf`, share);\n  }\n\n  // 3. Retailer Purchase & Coupon Summary PDF\n  async function downloadRetailerSummaryPDF(share = false) {\n    if (!window.jspdf) return printHTMLReport('SUMMARY');\n    const { jsPDF } = window.jspdf;\n    const doc = new jsPDF('l', 'mm', 'a4');\n    const totalKg = STATE.summaryRows.reduce((s, r) => s + r.total_kg, 0);\n    const totalEarned = STATE.summaryRows.reduce((s, r) => s + r.earned, 0);\n\n    drawPDFHeader(\n      doc,\n      'RETAILER-WISE PURCHASE, COUPON & PRIZE SUMMARY',\n      `Total Delivered: ${Math.round(totalKg*100)/100} kg  |  Total Earned: ${totalEarned}  |  Total Allotted: ${STATE.coupons.length}  |  Rule: 1 Coupon = ${STATE.settings.kg_per_coupon} kg`\n    );\n\n    const body = STATE.summaryRows.map((r, i) => [\n      i + 1,\n      pdfSafeText(r.name),\n      pdfSafeText(r.area || '-'),\n      r.equiv_bags,\n      `${r.total_kg} kg`,\n      r.earned,\n      r.issued,\n      r.pending,\n      pdfSafeText(r.coupons.map(c => '#' + c.coupon_code).join(', ') || '-'),\n      pdfSafeText(r.prizes.map(p => `#${p.coupon_code}: ${p.prize_title}`).join('; ') || '-')\n    ]);\n\n    doc.autoTable({\n      startY: 33,\n      head: [['#', 'Retailer Name', 'Area', 'Bags', 'Total KG', 'Earned', 'Issued', 'Pending', 'Coupon Numbers', 'Prizes Won']],\n      body,\n      theme: 'grid',\n      headStyles: { fillColor: [15, 23, 42], textColor: [251, 191, 36], fontSize: 8.5 },\n      bodyStyles: { fontSize: 8.2 },\n      alternateRowStyles: { fillColor: [248, 250, 252] },\n      margin: { bottom: 15 }\n    });\n\n    addPageFooters(doc);\n    await finishPDF(doc, `Aryush_Retailer_Summary_${todayISO()}.pdf`, share);\n  }\n\n  // 4. Handover Slips PDF\n  async function downloadHandoverSlipsPDF(share = false) {\n    if (!window.jspdf) return;\n    const { jsPDF } = window.jspdf;\n    const doc = new jsPDF('p', 'mm', 'a4');\n    const allottedRetailers = STATE.summaryRows.filter(r => r.coupons.length > 0);\n\n    drawPDFHeader(\n      doc,\n      'RETAILER COUPON ALLOTMENT & HANDOVER RECEIPT REGISTER',\n      `Retailers with Allotted Coupons: ${allottedRetailers.length}  |  Total Coupons: ${STATE.coupons.length}`\n    );\n\n    const body = allottedRetailers.map((r, idx) => [\n      idx + 1,\n      pdfSafeText(r.name),\n      `${r.total_kg} kg`,\n      r.coupons.length,\n      pdfSafeText(r.coupons.map(c => '#' + c.coupon_code).join(', ')),\n      ''\n    ]);\n\n    doc.autoTable({\n      startY: 33,\n      head: [['#', 'Retailer Name', 'Total KG', 'Qty', 'Allotted Coupon Numbers', 'Receiver Signature']],\n      body: body.length ? body : [['-', 'No coupons allotted yet', '-', '-', '-', '']],\n      theme: 'grid',\n      headStyles: { fillColor: [15, 23, 42], textColor: [251, 191, 36], fontSize: 9 },\n      bodyStyles: { fontSize: 8.8, minCellHeight: 10 },\n      columnStyles: { 5: { cellWidth: 36 } },\n      margin: { bottom: 15 }\n    });\n\n    addPageFooters(doc);\n    await finishPDF(doc, `Aryush_Coupon_Handover_List_${todayISO()}.pdf`, share);\n  }\n\n  // Unicode / Hindi Native A4 Print View\n  function printHTMLReport(mode) {\n    const s = STATE.settings;\n    const retById = new Map(STATE.summaryRows.map(r => [r.id, r]));\n    let title = '';\n    let tableHtml = '';\n\n    if (mode === 'WINNERS') {\n      title = 'OFFICIAL LUCKY DRAW PRIZE WINNERS REPORT';\n      const winners = [...STATE.coupons]\n        .filter(c => c.prize_status !== 'NONE' && c.prize_title)\n        .sort((a, b) => (a.prize_rank || 999) - (b.prize_rank || 999) || a.coupon_num - b.coupon_num);\n      tableHtml = `<table class=\"print-table\">\n        <thead><tr><th>Rank</th><th>Coupon No.</th><th>Retailer Name</th><th>Area / Phone</th><th>Prize Won</th><th>Status</th></tr></thead>\n        <tbody>${winners.map((c, i) => {\n          const r = retById.get(c.retailer_id);\n          return `<tr><td>${c.prize_rank < 999 ? c.prize_rank : i+1}</td><td><b>#${esc(c.coupon_code)}</b></td><td><b>${esc(r?.name||'-')}</b></td><td>${esc(r?.area||'')} ${esc(r?.phone||'')}</td><td><b>${esc(c.prize_title)}</b></td><td>${c.prize_status === 'DELIVERED' ? 'Handed Over' : 'Declared'}</td></tr>`;\n        }).join('') || '<tr><td colspan=\"6\">No winners declared yet</td></tr>'}</tbody></table>`;\n    } else if (mode === 'REGISTER') {\n      title = 'MEGA LUCKY DRAW COUPON & PRIZE REGISTER';\n      const maxC = Number(s.max_coupons) || 300;\n      const byNum = new Map(STATE.coupons.map(c => [Number(c.coupon_num), c]));\n      let rows = '';\n      for (let n = 1; n <= maxC; n++) {\n        const c = byNum.get(n);\n        const r = c ? retById.get(c.retailer_id) : null;\n        rows += `<tr><td><b>#${esc(padCouponNum(n))}</b></td><td>${esc(r?.name || '')}</td><td>${c ? formatDateDisplay(c.issue_date) : ''}</td><td><b>${esc(c?.prize_title || '')}</b></td></tr>`;\n      }\n      tableHtml = `<table class=\"print-table\"><thead><tr><th>Coupon No.</th><th>Retailer Name</th><th>Issue Date</th><th>Prize Won</th></tr></thead><tbody>${rows}</tbody></table>`;\n    } else {\n      title = 'RETAILER PURCHASE & COUPON SUMMARY';\n      tableHtml = `<table class=\"print-table\"><thead><tr><th>#</th><th>Retailer</th><th>Total KG</th><th>Earned</th><th>Issued</th><th>Coupon Nos.</th><th>Prizes</th></tr></thead>\n        <tbody>${STATE.summaryRows.map((r, i) => `<tr><td>${i+1}</td><td><b>${esc(r.name)}</b></td><td>${r.total_kg} kg</td><td>${r.earned}</td><td>${r.issued}</td><td>${esc(r.coupons.map(c=>'#'+c.coupon_code).join(', '))}</td><td>${esc(r.prizes.map(p=>p.prize_title).join(', '))}</td></tr>`).join('')}</tbody></table>`;\n    }\n\n    const sec = document.getElementById('printSection');\n    sec.innerHTML = `\n      <div style=\"text-align:center;border-bottom:2px solid #0f172a;padding-bottom:8px;\">\n        <h2 style=\"font-size:18px;\">${esc(s.company_name)} \u2014 ${esc(s.campaign_name)}</h2>\n        <div style=\"font-size:13px;font-weight:700;margin-top:2px;\">${title}</div>\n        <div style=\"font-size:11px;color:#475569;margin-top:2px;\">Date: ${formatDateDisplay(todayISO())} | 1 Coupon = ${s.kg_per_coupon} kg | Pool: ${s.max_coupons} Coupons</div>\n      </div>\n      ${tableHtml}\n      <div style=\"margin-top:28px;text-align:right;font-size:12px;font-weight:700;\">${esc(s.signatory)}</div>\n    `;\n    window.print();\n  }\n\n  // ================= INIT =================\n  window.addEventListener('DOMContentLoaded', () => {\n    document.getElementById('delDate').value = todayISO();\n    document.getElementById('bulkIssueDate').value = todayISO();\n    document.getElementById('przDrawDate').value = todayISO();\n    refreshAll();\n  });\n</script>\n</body>\n</html>\n";

const MANIFEST_JSON = JSON.stringify({
  name: "Aryush Lucky Draw Manager",
  short_name: "Aryush Draw",
  start_url: "/",
  display: "standalone",
  background_color: "#0f172a",
  theme_color: "#0f172a"
});

let schemaInitialized = false;

async function ensureSchema(db) {
  if (schemaInitialized) return;
  await db.batch([
    db.prepare(`CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)`),
    db.prepare(`CREATE TABLE IF NOT EXISTS retailers (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL UNIQUE,
      area TEXT DEFAULT '',
      phone TEXT DEFAULT '',
      created_at TEXT DEFAULT (datetime('now'))
    )`),
    db.prepare(`CREATE TABLE IF NOT EXISTS deliveries (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      dl_code TEXT NOT NULL UNIQUE,
      entry_date TEXT NOT NULL,
      retailer_id INTEGER NOT NULL,
      bags REAL NOT NULL DEFAULT 0,
      loose_kg REAL NOT NULL DEFAULT 0,
      total_kg REAL NOT NULL DEFAULT 0,
      remarks TEXT DEFAULT '',
      created_at TEXT DEFAULT (datetime('now'))
    )`),
    db.prepare(`CREATE TABLE IF NOT EXISTS coupons (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      coupon_num INTEGER NOT NULL UNIQUE,
      coupon_code TEXT NOT NULL UNIQUE,
      retailer_id INTEGER NOT NULL,
      issue_date TEXT NOT NULL,
      batch_ref TEXT DEFAULT '',
      prize_rank INTEGER DEFAULT 999,
      prize_title TEXT DEFAULT '',
      prize_value REAL DEFAULT 0,
      draw_date TEXT DEFAULT '',
      prize_status TEXT DEFAULT 'NONE',
      remarks TEXT DEFAULT '',
      created_at TEXT DEFAULT (datetime('now'))
    )`),
    db.prepare(`CREATE INDEX IF NOT EXISTS idx_deliveries_retailer ON deliveries(retailer_id)`),
    db.prepare(`CREATE INDEX IF NOT EXISTS idx_coupons_retailer ON coupons(retailer_id)`)
  ]);
  schemaInitialized = true;
}

function jsonResp(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "GET, POST, DELETE, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type"
    }
  });
}

async function getSettingsObj(db) {
  const defaults = {
    company_name: "ARYUSH FOODS",
    campaign_name: "MEGA ALTO LUCKY DRAW",
    kg_per_coupon: 210,
    kg_per_bag: 30,
    max_coupons: 300,
    coupon_prefix: "",
    signatory: "For Aryush Foods (Kailaras, Morena)"
  };
  const rows = await db.prepare("SELECT key, value FROM settings").all();
  for (const r of (rows.results || [])) {
    if (["kg_per_coupon", "kg_per_bag", "max_coupons"].includes(r.key)) {
      defaults[r.key] = Number(r.value);
    } else {
      defaults[r.key] = r.value;
    }
  }
  return defaults;
}

async function getOrCreateRetailerId(db, nameRaw, area = "", phone = "") {
  const name = String(nameRaw || "").trim().toUpperCase();
  if (!name) throw new Error("Retailer name is required");
  const existing = await db.prepare("SELECT id FROM retailers WHERE UPPER(name) = ?").bind(name).first();
  if (existing) {
    if (area || phone) {
      await db.prepare("UPDATE retailers SET area = COALESCE(NULLIF(?, ''), area), phone = COALESCE(NULLIF(?, ''), phone) WHERE id = ?")
        .bind(area, phone, existing.id).run();
    }
    return existing.id;
  }
  const ins = await db.prepare("INSERT INTO retailers (name, area, phone) VALUES (?, ?, ?) RETURNING id")
    .bind(name, area, phone).first();
  return ins.id;
}

function randomDlCode() {
  const bytes = new Uint8Array(5);
  crypto.getRandomValues(bytes);
  return "DL-" + Array.from(bytes).map(b => b.toString(16).padStart(2, "0")).join("").toUpperCase();
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (request.method === "OPTIONS") return jsonResp({ ok: true });

    // Serve PWA Manifest & Frontend
    if (url.pathname === "/manifest.json") {
      return new Response(MANIFEST_JSON, { headers: { "Content-Type": "application/json" } });
    }
    if (!url.pathname.startsWith("/api/")) {
      return new Response(INDEX_HTML, {
        headers: { "Content-Type": "text/html; charset=utf-8" }
      });
    }

    if (!env.DB) {
      return jsonResp({ error: "Cloudflare D1 binding 'DB' not configured! Bind your D1 database as 'DB' in Worker Settings -> Bindings." }, 500);
    }

    try {
      await ensureSchema(env.DB);
      const db = env.DB;

      // GET /api/bootstrap
      if (url.pathname === "/api/bootstrap" && request.method === "GET") {
        const [settings, retailers, deliveries, coupons] = await Promise.all([
          getSettingsObj(db),
          db.prepare("SELECT * FROM retailers ORDER BY name ASC").all(),
          db.prepare("SELECT * FROM deliveries ORDER BY entry_date DESC, id DESC").all(),
          db.prepare("SELECT * FROM coupons ORDER BY coupon_num ASC").all()
        ]);
        return jsonResp({
          settings,
          retailers: retailers.results || [],
          deliveries: deliveries.results || [],
          coupons: coupons.results || []
        });
      }

      // POST /api/settings
      if (url.pathname === "/api/settings" && request.method === "POST") {
        const body = await request.json();
        const stmts = Object.entries(body).map(([k, v]) =>
          db.prepare("INSERT INTO settings (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value")
            .bind(k, String(v ?? ""))
        );
        if (stmts.length) await db.batch(stmts);
        return jsonResp({ ok: true, settings: await getSettingsObj(db) });
      }

      // POST /api/retailers
      if (url.pathname === "/api/retailers" && request.method === "POST") {
        const body = await request.json();
        const id = await getOrCreateRetailerId(db, body.name, body.area || "", body.phone || "");
        const retailer = await db.prepare("SELECT * FROM retailers WHERE id = ?").bind(id).first();
        return jsonResp({ ok: true, retailer });
      }

      // DELETE /api/retailers/:id
      if (url.pathname.startsWith("/api/retailers/") && request.method === "DELETE") {
        const id = Number(url.pathname.split("/").pop());
        await db.batch([
          db.prepare("DELETE FROM coupons WHERE retailer_id = ?").bind(id),
          db.prepare("DELETE FROM deliveries WHERE retailer_id = ?").bind(id),
          db.prepare("DELETE FROM retailers WHERE id = ?").bind(id)
        ]);
        return jsonResp({ ok: true });
      }

      // POST /api/deliveries
      if (url.pathname === "/api/deliveries" && request.method === "POST") {
        const body = await request.json();
        const retailerId = body.retailer_id
          ? Number(body.retailer_id)
          : await getOrCreateRetailerId(db, body.retailer_name);

        const bags = Number(body.bags) || 0;
        const loose_kg = Number(body.loose_kg) || 0;
        const total_kg = Number(body.total_kg) || 0;
        const entry_date = String(body.entry_date || new Date().toISOString().slice(0, 10));
        const remarks = String(body.remarks || "");

        if (body.id) {
          await db.prepare(
            "UPDATE deliveries SET entry_date = ?, retailer_id = ?, bags = ?, loose_kg = ?, total_kg = ?, remarks = ? WHERE id = ?"
          ).bind(entry_date, retailerId, bags, loose_kg, total_kg, remarks, Number(body.id)).run();
        } else {
          await db.prepare(
            "INSERT INTO deliveries (dl_code, entry_date, retailer_id, bags, loose_kg, total_kg, remarks) VALUES (?, ?, ?, ?, ?, ?, ?)"
          ).bind(randomDlCode(), entry_date, retailerId, bags, loose_kg, total_kg, remarks).run();
        }
        return jsonResp({ ok: true });
      }

      // DELETE /api/deliveries/:id
      if (url.pathname.startsWith("/api/deliveries/") && request.method === "DELETE") {
        const id = Number(url.pathname.split("/").pop());
        await db.prepare("DELETE FROM deliveries WHERE id = ?").bind(id).run();
        return jsonResp({ ok: true });
      }

      // POST /api/coupons/allot (1-Click Ek Sath Bulk Allot + Custom Batch + Manual Single)
      if (url.pathname === "/api/coupons/allot" && request.method === "POST") {
        const body = await request.json();
        const settings = await getSettingsObj(db);
        const maxC = Number(settings.max_coupons) || 300;
        const prefix = settings.coupon_prefix || "";
        const digits = maxC >= 1000 ? 4 : 3;
        const issueDate = String(body.issue_date || new Date().toISOString().slice(0, 10));

        const existingRows = await db.prepare("SELECT coupon_num FROM coupons").all();
        const usedSet = new Set((existingRows.results || []).map(r => Number(r.coupon_num)));

        // Single manual coupon number
        if (body.manual_coupon_num) {
          const num = Number(body.manual_coupon_num);
          if (num < 1 || num > maxC) return jsonResp({ error: `Coupon number must be between 1 and ${maxC}` }, 400);
          if (usedSet.has(num)) return jsonResp({ error: `Coupon #${num} is already allotted!` }, 400);
          const code = prefix + String(num).padStart(digits, "0");
          await db.prepare(
            "INSERT INTO coupons (coupon_num, coupon_code, retailer_id, issue_date, batch_ref) VALUES (?, ?, ?, ?, 'MANUAL')"
          ).bind(num, code, Number(body.retailer_id), issueDate).run();
          return jsonResp({ ok: true, allotted: 1 });
        }

        // Batch / Ek Sath Allot
        const allocations = body.allocations || [];
        const totalNeeded = allocations.reduce((s, a) => s + (Number(a.count) || 0), 0);
        if (totalNeeded <= 0) return jsonResp({ error: "No pending coupons to allot" }, 400);

        const available = [];
        for (let i = 1; i <= maxC; i++) {
          if (!usedSet.has(i)) available.push(i);
        }

        if (totalNeeded > available.length) {
          return jsonResp({
            error: `Only ${available.length} coupons remaining in pool (Max ${maxC}), cannot allot ${totalNeeded}. Increase Max Coupons in Settings if needed.`
          }, 400);
        }

        if (body.mode === "random") {
          for (let i = available.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [available[i], available[j]] = [available[j], available[i]];
          }
        }

        const batchRef = "BATCH-" + Date.now().toString(36).toUpperCase();
        const stmts = [];
        let ptr = 0;
        for (const item of allocations) {
          const cnt = Number(item.count) || 0;
          const rId = Number(item.retailer_id);
          for (let k = 0; k < cnt; k++) {
            const num = available[ptr++];
            const code = prefix + String(num).padStart(digits, "0");
            stmts.push(
              db.prepare("INSERT INTO coupons (coupon_num, coupon_code, retailer_id, issue_date, batch_ref) VALUES (?, ?, ?, ?, ?)")
                .bind(num, code, rId, issueDate, batchRef)
            );
          }
        }

        // Chunk D1 batch in groups of 80 statements for safety
        for (let i = 0; i < stmts.length; i += 80) {
          await db.batch(stmts.slice(i, i + 80));
        }

        return jsonResp({ ok: true, allotted: totalNeeded });
      }

      // DELETE /api/coupons/:id
      if (url.pathname.startsWith("/api/coupons/") && request.method === "DELETE") {
        const id = Number(url.pathname.split("/").pop());
        await db.prepare("DELETE FROM coupons WHERE id = ?").bind(id).run();
        return jsonResp({ ok: true });
      }

      // POST /api/coupons/prize
      if (url.pathname === "/api/coupons/prize" && request.method === "POST") {
        const body = await request.json();
        const title = String(body.prize_title || "").trim();
        const rank = title ? (Number(body.prize_rank) || 99) : 999;
        const status = title ? String(body.prize_status || "WON") : "NONE";
        const drawDate = String(body.draw_date || "");
        const remarks = String(body.remarks || "");

        await db.prepare(
          "UPDATE coupons SET prize_title = ?, prize_rank = ?, draw_date = ?, prize_status = ?, remarks = ? WHERE id = ?"
        ).bind(title, rank, drawDate, status, remarks, Number(body.coupon_id)).run();
        return jsonResp({ ok: true });
      }

      // POST /api/import (Bulk Sheet Paste & Full JSON Backup Restore)
      if (url.pathname === "/api/import" && request.method === "POST") {
        const body = await request.json();

        if (body.full_restore) {
          await db.batch([
            db.prepare("DELETE FROM coupons"),
            db.prepare("DELETE FROM deliveries"),
            db.prepare("DELETE FROM retailers")
          ]);
          if (body.settings) {
            const sStmts = Object.entries(body.settings).map(([k, v]) =>
              db.prepare("INSERT INTO settings (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value").bind(k, String(v ?? ""))
            );
            if (sStmts.length) await db.batch(sStmts);
          }
          for (const r of (body.retailers || [])) {
            await db.prepare("INSERT INTO retailers (id, name, area, phone) VALUES (?, ?, ?, ?)").bind(r.id, r.name, r.area || "", r.phone || "").run();
          }
          for (const d of (body.deliveries || [])) {
            await db.prepare("INSERT INTO deliveries (id, dl_code, entry_date, retailer_id, bags, loose_kg, total_kg, remarks) VALUES (?, ?, ?, ?, ?, ?, ?, ?)")
              .bind(d.id, d.dl_code, d.entry_date, d.retailer_id, d.bags, d.loose_kg, d.total_kg, d.remarks || "").run();
          }
          for (const c of (body.coupons || [])) {
            await db.prepare("INSERT INTO coupons (id, coupon_num, coupon_code, retailer_id, issue_date, batch_ref, prize_rank, prize_title, prize_value, draw_date, prize_status, remarks) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
              .bind(c.id, c.coupon_num, c.coupon_code, c.retailer_id, c.issue_date, c.batch_ref || "", c.prize_rank ?? 999, c.prize_title || "", c.prize_value || 0, c.draw_date || "", c.prize_status || "NONE", c.remarks || "").run();
          }
          return jsonResp({ ok: true });
        }

        for (const rName of (body.retailers || [])) {
          if (String(rName || "").trim()) await getOrCreateRetailerId(db, rName);
        }

        for (const d of (body.deliveries || [])) {
          const rId = await getOrCreateRetailerId(db, d.retailer_name);
          await db.prepare(
            "INSERT INTO deliveries (dl_code, entry_date, retailer_id, bags, loose_kg, total_kg, remarks) VALUES (?, ?, ?, ?, ?, ?, ?)"
          ).bind(randomDlCode(), d.entry_date, rId, Number(d.bags) || 0, Number(d.loose_kg) || 0, Number(d.total_kg) || 0, String(d.remarks || "")).run();
        }

        return jsonResp({ ok: true });
      }

      return jsonResp({ error: "API route not found" }, 404);
    } catch (err) {
      return jsonResp({ error: err.message || "Internal Worker Error" }, 500);
    }
  }
};
